import{e as s,w as l}from"./chunk-EZ53O34Q.js";import"./chunk-V3DKI4G4.js";s();var u=[["Main-site product search","B\xFAsqueda de productos del sitio principal","Produktsuche der Hauptseite","Recherche de produits du site principal","Ricerca prodotti del sito principale"],["Search the catalog or open a matched product","Busca en el cat\xE1logo o abre un producto vinculado","Katalog durchsuchen oder ein passendes Produkt \xF6ffnen","Recherchez dans le catalogue ou ouvrez un produit associ\xE9","Cerca nel catalogo o apri un prodotto abbinato"],["Use the search box to send your exact keyword to the main catalog. Every product image below is paired with its corresponding main-site item page.","Usa el buscador para enviar la palabra exacta al cat\xE1logo principal. Cada imagen de producto est\xE1 vinculada a la p\xE1gina correspondiente del sitio principal.","Sende dein genaues Stichwort \xFCber das Suchfeld an den Hauptkatalog. Jedes Produktbild unten ist mit der passenden Artikelseite der Hauptseite verkn\xFCpft.","Utilisez le champ de recherche pour envoyer votre mot-cl\xE9 exact au catalogue principal. Chaque image produit est associ\xE9e \xE0 la page correspondante du site principal.","Usa il campo di ricerca per inviare la parola chiave esatta al catalogo principale. Ogni immagine \xE8 abbinata alla pagina corrispondente del sito principale."],["Browse by product type","Explorar por tipo de producto","Nach Produkttyp st\xF6bern","Parcourir par type de produit","Esplora per tipo di prodotto"],["Choose a category before narrowing the item","Elige una categor\xEDa antes de concretar el art\xEDculo","Erst eine Kategorie, dann den Artikel eingrenzen","Choisissez une cat\xE9gorie avant de pr\xE9ciser l'article","Scegli una categoria prima di restringere l'articolo"],["Category links lead only to the matching section of the main catalog. Use them for broad browsing, then confirm the exact variant on the product page.","Los enlaces de categor\xEDa llevan \xFAnicamente a la secci\xF3n correspondiente del cat\xE1logo principal. \xDAsalos para explorar de forma general y confirma despu\xE9s la variante exacta en la p\xE1gina del producto.","Kategorielinks f\xFChren nur zum passenden Bereich des Hauptkatalogs. Nutze sie zum allgemeinen St\xF6bern und pr\xFCfe anschlie\xDFend die genaue Variante auf der Produktseite.","Les liens de cat\xE9gorie m\xE8nent uniquement \xE0 la section correspondante du catalogue principal. Utilisez-les pour parcourir largement, puis confirmez la variante exacte sur la page produit.","I link di categoria portano solo alla sezione corrispondente del catalogo principale. Usali per una ricerca ampia, poi conferma la variante esatta nella pagina prodotto."],["Warehouse-photo review","Revisi\xF3n de fotos de almac\xE9n","Pr\xFCfung der Lagerfotos","Examen des photos d'entrep\xF4t","Controllo delle foto di magazzino"],["A practical QC checklist before parcel submission","Una lista pr\xE1ctica de QC antes de enviar el paquete","Praktische QC-Checkliste vor der Paketeinreichung","Liste QC pratique avant la soumission du colis","Checklist QC pratica prima dell'invio del pacco"],["QC photos are most useful when you ask specific, visible questions. This guide helps you compare the received item with the option you selected.","Las fotos de QC son m\xE1s \xFAtiles cuando planteas preguntas concretas y visibles. Esta gu\xEDa te ayuda a comparar el art\xEDculo recibido con la opci\xF3n que elegiste.","QC-Fotos sind am n\xFCtzlichsten, wenn du konkrete, sichtbare Fragen stellst. Dieser Ratgeber hilft, den erhaltenen Artikel mit der gew\xE4hlten Option zu vergleichen.","Les photos QC sont particuli\xE8rement utiles pour r\xE9pondre \xE0 des questions pr\xE9cises et visibles. Ce guide vous aide \xE0 comparer l'article re\xE7u avec l'option choisie.","Le foto QC sono pi\xF9 utili quando poni domande specifiche e visibili. Questa guida aiuta a confrontare l'articolo ricevuto con l'opzione selezionata."],["International parcel planning","Planificaci\xF3n de paquetes internacionales","Internationale Paketplanung","Planification d'un colis international","Pianificazione del pacco internazionale"],["Understand what can change the shipping total","Entiende qu\xE9 puede cambiar el coste total del env\xEDo","Verstehe, was die gesamten Versandkosten ver\xE4ndern kann","Comprenez ce qui peut modifier le co\xFBt total de livraison","Scopri cosa pu\xF2 cambiare il costo totale della spedizione"],["Destination, route restrictions, chargeable weight, parcel dimensions and packing choices can all affect a shipment. Plan with realistic inputs instead of a product-price guess.","El destino, las restricciones de ruta, el peso facturable, las dimensiones y el embalaje pueden afectar al env\xEDo. Planifica con datos realistas, no con una suposici\xF3n basada en el precio del producto.","Ziel, Routenbeschr\xE4nkungen, abrechenbares Gewicht, Paketma\xDFe und Verpackung k\xF6nnen den Versand beeinflussen. Plane mit realistischen Angaben statt mit einer Sch\xE4tzung anhand des Produktpreises.","La destination, les restrictions de ligne, le poids facturable, les dimensions et l'emballage peuvent influencer l'envoi. Planifiez avec des donn\xE9es r\xE9alistes plut\xF4t qu'en vous basant sur le prix du produit.","Destinazione, restrizioni della linea, peso addebitabile, dimensioni e imballaggio possono influire sulla spedizione. Pianifica con dati realistici invece di dedurre dal prezzo del prodotto."],["LoloBuy learning center","Centro de aprendizaje de LoloBuy","LoloBuy Lerncenter","Centre d'apprentissage LoloBuy","Centro guide LoloBuy"],["Research the listing before you place an order","Investiga el anuncio antes de hacer un pedido","Angebot vor der Bestellung pr\xFCfen","\xC9tudiez l'annonce avant de commander","Esamina l'inserzione prima di ordinare"],["These independent guides focus on the decisions a product spreadsheet cannot make for you: variant selection, visible QC, parcel planning and link checks.","Estas gu\xEDas independientes se centran en decisiones que una hoja de productos no puede tomar por ti: elegir la variante, revisar el QC visible, planificar el paquete y comprobar los enlaces.","Diese unabh\xE4ngigen Ratgeber behandeln Entscheidungen, die ein Produkt-Spreadsheet nicht f\xFCr dich treffen kann: Variantenwahl, sichtbare QC-Pr\xFCfung, Paketplanung und Linkkontrolle.","Ces guides ind\xE9pendants portent sur les d\xE9cisions qu'une feuille de produits ne peut pas prendre \xE0 votre place : choix de la variante, QC visible, planification du colis et v\xE9rification des liens.","Queste guide indipendenti trattano decisioni che un foglio prodotti non pu\xF2 prendere al posto tuo: scelta della variante, QC visibile, pianificazione del pacco e verifica dei link."],["Independent buying guides","Gu\xEDas de compra independientes","Unabh\xE4ngige Kaufratgeber","Guides d'achat ind\xE9pendants","Guide d'acquisto indipendenti"],["Practical LoloBuy buying guides for better decisions","Gu\xEDas pr\xE1cticas de compra de LoloBuy para tomar mejores decisiones","Praktische LoloBuy-Kaufratgeber f\xFCr bessere Entscheidungen","Guides d'achat LoloBuy pratiques pour de meilleures d\xE9cisions","Guide pratiche all'acquisto LoloBuy per decisioni migliori"],["Use focused guides for product discovery, listing checks, warehouse-photo review and parcel planning. Each article answers a real question instead of repeating a keyword.","Usa gu\xEDas espec\xEDficas para descubrir productos, revisar anuncios y fotos de almac\xE9n y planificar paquetes. Cada art\xEDculo responde una pregunta real en lugar de repetir una palabra clave.","Nutze gezielte Ratgeber f\xFCr Produktsuche, Angebotspr\xFCfung, Lagerfoto-Kontrolle und Paketplanung. Jeder Artikel beantwortet eine echte Frage, statt ein Stichwort zu wiederholen.","Utilisez des guides cibl\xE9s pour d\xE9couvrir des produits, v\xE9rifier les annonces et les photos d'entrep\xF4t et planifier les colis. Chaque article r\xE9pond \xE0 une vraie question au lieu de r\xE9p\xE9ter un mot-cl\xE9.","Usa guide mirate per ricerca prodotti, verifica delle inserzioni, controllo delle foto di magazzino e pianificazione del pacco. Ogni articolo risponde a una domanda reale invece di ripetere una parola chiave."],["Clear, fact-conscious answers","Respuestas claras y basadas en hechos","Klare, faktenbewusste Antworten","R\xE9ponses claires et factuelles","Risposte chiare e attente ai fatti"],["Frequently asked questions about this LoloBuy sheet","Preguntas frecuentes sobre esta hoja LoloBuy","H\xE4ufige Fragen zu diesem LoloBuy Sheet","Questions fr\xE9quentes sur cette feuille LoloBuy","Domande frequenti su questo foglio LoloBuy"],["Understand what this independent directory does, where its product links go, what QC photos can show and why shipping estimates can change.","Entiende qu\xE9 hace este directorio independiente, ad\xF3nde llevan sus enlaces, qu\xE9 pueden mostrar las fotos de QC y por qu\xE9 pueden cambiar las estimaciones de env\xEDo.","Erfahre, was dieses unabh\xE4ngige Verzeichnis leistet, wohin die Produktlinks f\xFChren, was QC-Fotos zeigen k\xF6nnen und warum sich Versandsch\xE4tzungen \xE4ndern.","Comprenez le r\xF4le de ce r\xE9pertoire ind\xE9pendant, la destination de ses liens produit, ce que montrent les photos QC et pourquoi les estimations de livraison peuvent changer.","Scopri cosa fa questa directory indipendente, dove portano i link prodotto, cosa mostrano le foto QC e perch\xE9 le stime di spedizione possono cambiare."],["From product find to parcel","Del producto encontrado al paquete","Vom Produktfund zum Paket","De la trouvaille au colis","Dal prodotto trovato al pacco"],["How to use the sheet without losing the product context","C\xF3mo usar la hoja sin perder el contexto del producto","So nutzt du das Sheet, ohne den Produktkontext zu verlieren","Comment utiliser la feuille sans perdre le contexte du produit","Come usare il foglio senza perdere il contesto del prodotto"],["Start with a matched item, verify the listing, submit the original marketplace link through your chosen purchasing flow, and inspect the warehouse result before shipping.","Empieza con un art\xEDculo vinculado, verifica el anuncio, env\xEDa el enlace original mediante el proceso de compra elegido y revisa el resultado del almac\xE9n antes del env\xEDo.","Beginne mit einem zugeordneten Artikel, pr\xFCfe das Angebot, \xFCbermittle den urspr\xFCnglichen Marktplatz-Link \xFCber deinen gew\xE4hlten Kaufablauf und kontrolliere das Lagerergebnis vor dem Versand.","Commencez par un article associ\xE9, v\xE9rifiez l'annonce, soumettez le lien d'origine via votre processus d'achat et inspectez le r\xE9sultat en entrep\xF4t avant l'exp\xE9dition.","Parti da un articolo abbinato, verifica l'inserzione, invia il link originale tramite il flusso d'acquisto scelto e controlla il risultato in magazzino prima della spedizione."],["Search destination: your main catalog","Destino de b\xFAsqueda: tu cat\xE1logo principal","Suchziel: dein Hauptkatalog","Destination de recherche : votre catalogue principal","Destinazione della ricerca: il tuo catalogo principale"],["Keep the keyword intact","Mant\xE9n intacta la palabra clave","Suchbegriff unver\xE4ndert lassen","Conservez le mot-cl\xE9 intact","Mantieni intatta la parola chiave"],["Enter a product name, style or item type. The same text is passed as the search query, so \u201Cshoes\u201D opens shoe results rather than a generic all-products landing page.","Introduce un nombre, estilo o tipo de art\xEDculo. El mismo texto se env\xEDa como consulta, por lo que \xABcalzado\xBB abre resultados de calzado y no una p\xE1gina gen\xE9rica con todos los productos.","Gib Produktname, Stil oder Artikeltyp ein. Derselbe Text wird als Suche \xFCbergeben, sodass \u201ESchuhe\u201C passende Ergebnisse statt einer allgemeinen Produktseite \xF6ffnet.","Saisissez un nom de produit, un style ou un type d'article. Le m\xEAme texte est transmis \xE0 la recherche, ainsi \xAB chaussures \xBB ouvre les r\xE9sultats correspondants plut\xF4t qu'une page g\xE9n\xE9rale.","Inserisci nome, stile o tipo di articolo. Lo stesso testo viene inviato come ricerca, quindi \u201Cscarpe\u201D apre i risultati relativi invece di una pagina generica."],["Matched product sample","Muestra de productos vinculados","Auswahl zugeordneter Produkte","Exemple de produits associ\xE9s","Esempio di prodotti abbinati"],["Image, title and item page stay together","Imagen, t\xEDtulo y p\xE1gina permanecen vinculados","Bild, Titel und Artikelseite bleiben zusammen","Image, titre et page produit restent associ\xE9s","Immagine, titolo e pagina restano abbinati"],["Each card uses a locally served copy of the item's main image and links to its exact main-site detail page.","Cada tarjeta usa una copia local de la imagen principal del art\xEDculo y enlaza con su p\xE1gina exacta del sitio principal.","Jede Karte nutzt eine lokal bereitgestellte Kopie des Hauptbilds und verlinkt auf die genaue Detailseite der Hauptseite.","Chaque fiche utilise une copie locale de l'image principale et renvoie vers sa page pr\xE9cise sur le site principal.","Ogni scheda usa una copia locale dell'immagine principale e collega alla pagina esatta del sito principale."],["Browse the full main catalog","Explorar el cat\xE1logo principal completo","Vollst\xE4ndigen Hauptkatalog ansehen","Parcourir tout le catalogue principal","Esplora tutto il catalogo principale"],["Recheck availability, size, color and seller details before use.","Vuelve a comprobar disponibilidad, talla, color y datos del vendedor antes de usarlo.","Pr\xFCfe Verf\xFCgbarkeit, Gr\xF6\xDFe, Farbe und Verk\xE4uferangaben vor der Nutzung erneut.","Rev\xE9rifiez la disponibilit\xE9, la taille, la couleur et les informations du vendeur avant utilisation.","Ricontrolla disponibilit\xE0, taglia, colore e dati del venditore prima dell'uso."],["Cross-category sample","Muestra de varias categor\xEDas","Kategorie\xFCbergreifende Auswahl","Exemple multiclasse","Esempio tra categorie"],["Compare the listing, not only the thumbnail","Compara el anuncio, no solo la miniatura","Angebot vergleichen, nicht nur das Vorschaubild","Comparez l'annonce, pas seulement la miniature","Confronta l'inserzione, non solo la miniatura"],["A single marketplace page may contain several colors, sizes or versions. Open the exact item page before deciding.","Una sola p\xE1gina del mercado puede contener varios colores, tallas o versiones. Abre la p\xE1gina exacta del art\xEDculo antes de decidir.","Eine Marktplatzseite kann mehrere Farben, Gr\xF6\xDFen oder Versionen enthalten. \xD6ffne vor der Entscheidung die genaue Artikelseite.","Une seule page de marketplace peut contenir plusieurs couleurs, tailles ou versions. Ouvrez la page exacte avant de d\xE9cider.","Una pagina del marketplace pu\xF2 contenere pi\xF9 colori, taglie o versioni. Apri la pagina esatta prima di decidere."],["Confirm item identity","Confirma la identidad del art\xEDculo","Artikelidentit\xE4t best\xE4tigen","Confirmez l'identit\xE9 de l'article","Conferma l'identit\xE0 dell'articolo"],["Compare the received item with the ordered title, selected option and recognizable design details. A similar-looking thumbnail is not enough.","Compara el art\xEDculo recibido con el t\xEDtulo pedido, la opci\xF3n elegida y los detalles reconocibles del dise\xF1o. Una miniatura parecida no es suficiente.","Vergleiche den erhaltenen Artikel mit bestelltem Titel, gew\xE4hlter Option und erkennbaren Designdetails. Ein \xE4hnlich aussehendes Vorschaubild reicht nicht.","Comparez l'article re\xE7u avec le titre command\xE9, l'option choisie et les d\xE9tails reconnaissables. Une miniature ressemblante ne suffit pas.","Confronta l'articolo ricevuto con titolo ordinato, opzione selezionata e dettagli riconoscibili. Una miniatura simile non basta."],["Correct item type and model","Tipo y modelo correctos","Richtiger Artikeltyp und Modell","Type et mod\xE8le corrects","Tipo e modello corretti"],["Correct color or listed variant","Color o variante indicados correctos","Richtige Farbe oder aufgef\xFChrte Variante","Couleur ou variante indiqu\xE9e correcte","Colore o variante indicata corretti"],["Expected accessories or parts visible","Accesorios o piezas esperados visibles","Erwartetes Zubeh\xF6r oder Teile sichtbar","Accessoires ou pi\xE8ces attendus visibles","Accessori o parti previsti visibili"],["Check labels and sizing","Revisa las etiquetas y la talla","Etiketten und Gr\xF6\xDFen pr\xFCfen","V\xE9rifiez les \xE9tiquettes et la taille","Controlla etichette e taglia"],["Look for a visible size label and compare it with the order record. When measurements matter, ask for a useful measuring angle rather than assuming fit from the tag alone.","Busca una etiqueta de talla visible y comp\xE1rala con el pedido. Si las medidas importan, solicita un \xE1ngulo \xFAtil de medici\xF3n en lugar de asumir el ajuste solo por la etiqueta.","Suche nach einem sichtbaren Gr\xF6\xDFenetikett und vergleiche es mit der Bestellung. Wenn Ma\xDFe wichtig sind, bitte um eine sinnvolle Messaufnahme, statt die Passform nur vom Etikett abzuleiten.","Recherchez une \xE9tiquette de taille visible et comparez-la \xE0 la commande. Si les mesures comptent, demandez un angle de mesure utile plut\xF4t que de d\xE9duire la coupe de l'\xE9tiquette.","Cerca un'etichetta della taglia visibile e confrontala con l'ordine. Se le misure contano, chiedi un'angolazione utile invece di dedurre la vestibilit\xE0 dall'etichetta."],["Review visible condition","Revisa el estado visible","Sichtbaren Zustand pr\xFCfen","Examinez l'\xE9tat visible","Controlla le condizioni visibili"],["Inspect the front, back, sides and any area that could have been compressed or damaged in domestic transit.","Inspecciona la parte delantera, trasera, los laterales y cualquier zona que pudiera haberse comprimido o da\xF1ado durante el transporte nacional.","Pr\xFCfe Vorderseite, R\xFCckseite, Seiten und alle Bereiche, die beim Inlandsversand gequetscht oder besch\xE4digt worden sein k\xF6nnten.","Inspectez l'avant, l'arri\xE8re, les c\xF4t\xE9s et toute zone susceptible d'avoir \xE9t\xE9 comprim\xE9e ou endommag\xE9e pendant le transport national.","Controlla fronte, retro, lati e ogni area che potrebbe essersi compressa o danneggiata durante il trasporto nazionale."],["Marks, tears or obvious deformation","Marcas, roturas o deformaciones evidentes","Spuren, Risse oder deutliche Verformung","Marques, d\xE9chirures ou d\xE9formation \xE9vidente","Segni, strappi o deformazioni evidenti"],["Missing pieces or detached hardware","Piezas faltantes o herrajes sueltos","Fehlende Teile oder gel\xF6ste Beschl\xE4ge","Pi\xE8ces manquantes ou \xE9l\xE9ments d\xE9tach\xE9s","Parti mancanti o componenti staccati"],["Large visible differences from the listing","Grandes diferencias visibles respecto al anuncio","Deutliche sichtbare Abweichungen vom Angebot","Diff\xE9rences visibles importantes avec l'annonce","Differenze visibili importanti rispetto all'inserzione"],["Know the limits of QC","Conoce los l\xEDmites del QC","Grenzen der QC-Pr\xFCfung kennen","Connaissez les limites du QC","Conosci i limiti del QC"],["Photos can reveal visible problems, but cannot guarantee fit, hidden construction, material composition, authenticity, durability or long-term performance.","Las fotos pueden mostrar problemas visibles, pero no garantizan el ajuste, la construcci\xF3n interna, la composici\xF3n, la autenticidad, la durabilidad ni el rendimiento a largo plazo.","Fotos k\xF6nnen sichtbare Probleme zeigen, garantieren aber weder Passform, verborgene Verarbeitung, Materialzusammensetzung, Echtheit, Haltbarkeit noch langfristige Leistung.","Les photos peuvent r\xE9v\xE9ler des probl\xE8mes visibles, mais ne garantissent ni la coupe, la construction cach\xE9e, la composition, l'authenticit\xE9, la durabilit\xE9 ou la performance \xE0 long terme.","Le foto possono mostrare problemi visibili, ma non garantiscono vestibilit\xE0, costruzione interna, composizione, autenticit\xE0, durata o prestazioni nel tempo."],["Destination and route","Destino y ruta","Ziel und Route","Destination et ligne","Destinazione e linea"],["Available lines and restrictions depend on the delivery country, item type, parcel weight and carrier rules. Compare only the routes actually available for the packed parcel.","Las l\xEDneas y restricciones disponibles dependen del pa\xEDs, el tipo de art\xEDculo, el peso del paquete y las reglas del transportista. Compara solo las rutas disponibles para el paquete embalado.","Verf\xFCgbare Linien und Beschr\xE4nkungen h\xE4ngen von Lieferland, Artikeltyp, Paketgewicht und Regeln des Dienstleisters ab. Vergleiche nur Routen, die f\xFCr das gepackte Paket tats\xE4chlich verf\xFCgbar sind.","Les lignes et restrictions disponibles d\xE9pendent du pays, du type d'article, du poids et des r\xE8gles du transporteur. Comparez uniquement les lignes r\xE9ellement disponibles pour le colis emball\xE9.","Linee e restrizioni disponibili dipendono da paese, tipo di articolo, peso e regole del vettore. Confronta solo le linee realmente disponibili per il pacco imballato."],["Actual and volumetric weight","Peso real y volum\xE9trico","Tats\xE4chliches und volumetrisches Gewicht","Poids r\xE9el et volum\xE9trique","Peso reale e volumetrico"],["A bulky light parcel may be charged by dimensions on routes using volumetric weight. Packaging decisions can therefore change the billable result.","Un paquete voluminoso y ligero puede cobrarse por dimensiones en rutas que usan peso volum\xE9trico. Las decisiones de embalaje pueden cambiar el resultado facturable.","Ein gro\xDFes, leichtes Paket kann auf Routen mit Volumengewicht nach Abmessungen berechnet werden. Verpackungsentscheidungen k\xF6nnen daher das abrechenbare Ergebnis ver\xE4ndern.","Un colis volumineux et l\xE9ger peut \xEAtre factur\xE9 selon ses dimensions sur les lignes au poids volum\xE9trique. Les choix d'emballage peuvent donc modifier le montant facturable.","Un pacco voluminoso e leggero pu\xF2 essere addebitato in base alle dimensioni sulle linee a peso volumetrico. Le scelte d'imballaggio possono cambiare il costo."],["Consolidation","Consolidaci\xF3n","Zusammenlegung","Consolidation","Consolidamento"],["Combining items may reduce repeated base charges, while an oversized or mixed parcel can narrow route choices. Group products with the final parcel size in mind.","Combinar art\xEDculos puede reducir cargos base repetidos, mientras que un paquete sobredimensionado o mixto puede limitar las rutas. Agrupa los productos pensando en el tama\xF1o final.","Das Zusammenlegen kann wiederholte Grundgeb\xFChren senken, w\xE4hrend ein \xFCbergro\xDFes oder gemischtes Paket die Routenauswahl einschr\xE4nken kann. Gruppiere Produkte mit Blick auf die Endgr\xF6\xDFe.","Regrouper des articles peut r\xE9duire les frais de base r\xE9p\xE9t\xE9s, tandis qu'un colis surdimensionn\xE9 ou mixte peut limiter le choix de lignes. Regroupez en pensant \xE0 la taille finale.","Unire gli articoli pu\xF2 ridurre costi base ripetuti, mentre un pacco sovradimensionato o misto pu\xF2 limitare le linee. Raggruppa pensando alle dimensioni finali."],["Packing choices","Opciones de embalaje","Verpackungsoptionen","Choix d'emballage","Scelte d'imballaggio"],["Boxes, corner protection, moisture barriers and extra cushioning add protection but can also add weight or dimensions. Choose them for the item's real risk.","Las cajas, protectores de esquinas, barreras antihumedad y acolchado extra a\xF1aden protecci\xF3n, pero tambi\xE9n peso o volumen. El\xEDgelos seg\xFAn el riesgo real del art\xEDculo.","Kartons, Eckenschutz, Feuchtigkeitssperren und zus\xE4tzliche Polsterung sch\xFCtzen, erh\xF6hen aber auch Gewicht oder Ma\xDFe. W\xE4hle sie nach dem tats\xE4chlichen Risiko des Artikels.","Les bo\xEEtes, protections d'angle, barri\xE8res contre l'humidit\xE9 et rembourrages prot\xE8gent, mais ajoutent aussi du poids ou du volume. Choisissez-les selon le risque r\xE9el.","Scatole, protezioni angolari, barriere antiumidit\xE0 e imbottitura proteggono, ma aggiungono peso o volume. Sceglile in base al rischio reale."],["Planning rule","Regla de planificaci\xF3n","Planungsregel","R\xE8gle de planification","Regola di pianificazione"],["Estimate early, decide after warehouse data is available","Estima pronto y decide cuando haya datos del almac\xE9n","Fr\xFCh sch\xE4tzen, nach Lagerdaten entscheiden","Estimez t\xF4t, d\xE9cidez avec les donn\xE9es d'entrep\xF4t","Stima prima, decidi dopo i dati di magazzino"],["An early estimate is useful for budgeting, but the final comparison should use the packed parcel's actual measurements and current route availability. Do not treat a sample figure as a guaranteed charge.","Una estimaci\xF3n inicial ayuda a presupuestar, pero la comparaci\xF3n final debe usar las medidas reales del paquete y las rutas disponibles. No trates una cifra de ejemplo como un coste garantizado.","Eine fr\xFChe Sch\xE4tzung hilft bei der Budgetplanung, doch der endg\xFCltige Vergleich sollte die tats\xE4chlichen Ma\xDFe des gepackten Pakets und aktuelle Routen nutzen. Ein Beispielwert ist kein garantierter Preis.","Une estimation initiale aide \xE0 budg\xE9ter, mais la comparaison finale doit utiliser les mesures r\xE9elles du colis et les lignes disponibles. Ne consid\xE9rez pas un exemple comme un tarif garanti.","Una stima iniziale aiuta il budget, ma il confronto finale deve usare misure reali del pacco e linee disponibili. Non considerare un valore d'esempio come costo garantito."],["Browse main-site products","Ver productos del sitio principal","Produkte der Hauptseite ansehen","Voir les produits du site principal","Vedi i prodotti del sito principale"],["How to use a LoloBuy spreadsheet without losing the source link","C\xF3mo usar una hoja LoloBuy sin perder el enlace de origen","So nutzt du ein LoloBuy Spreadsheet, ohne den Quelllink zu verlieren","Comment utiliser une feuille LoloBuy sans perdre le lien source","Come usare un foglio LoloBuy senza perdere il link originale"],["A useful spreadsheet shortens product discovery, but the purchasing decision still depends on the original listing, the selected variant and a clear record of what you intend to order.","Una hoja \xFAtil acorta la b\xFAsqueda, pero la decisi\xF3n de compra sigue dependiendo del anuncio original, la variante elegida y un registro claro de lo que quieres pedir.","Ein n\xFCtzliches Spreadsheet verk\xFCrzt die Produktsuche, doch die Kaufentscheidung h\xE4ngt weiterhin vom Originalangebot, der gew\xE4hlten Variante und einer klaren Bestellnotiz ab.","Une feuille utile raccourcit la d\xE9couverte, mais la d\xE9cision d'achat d\xE9pend toujours de l'annonce d'origine, de la variante choisie et d'un relev\xE9 clair de ce que vous souhaitez commander.","Un foglio utile riduce la ricerca, ma la decisione d'acquisto dipende ancora dall'inserzione originale, dalla variante scelta e da una nota chiara su ci\xF2 che vuoi ordinare."],["Read the buying-flow article","Leer el art\xEDculo sobre el proceso de compra","Artikel zum Kaufablauf lesen","Lire l'article sur le processus d'achat","Leggi l'articolo sulla procedura d'acquisto"],["How to read LoloBuy QC photos before parcel submission","C\xF3mo leer las fotos de QC de LoloBuy antes de enviar el paquete","So pr\xFCfst du LoloBuy QC-Fotos vor der Paketeinreichung","Comment lire les photos QC LoloBuy avant de soumettre le colis","Come leggere le foto QC LoloBuy prima di inviare il pacco"],["Review visible identity first, then the selected color or variant, size label, condition and the product-specific details that matter to your order.","Revisa primero la identidad visible; despu\xE9s el color o la variante, la etiqueta de talla, el estado y los detalles espec\xEDficos importantes para tu pedido.","Pr\xFCfe zuerst die sichtbare Identit\xE4t, dann gew\xE4hlte Farbe oder Variante, Gr\xF6\xDFenetikett, Zustand und die f\xFCr deine Bestellung wichtigen Details.","V\xE9rifiez d'abord l'identit\xE9 visible, puis la couleur ou variante choisie, l'\xE9tiquette de taille, l'\xE9tat et les d\xE9tails importants pour votre commande.","Controlla prima l'identit\xE0 visibile, poi colore o variante, etichetta della taglia, condizioni e dettagli importanti per l'ordine."],["Read the QC article","Leer el art\xEDculo de QC","QC-Artikel lesen","Lire l'article QC","Leggi l'articolo QC"],["LoloBuy shipping cost factors: weight, volume and route limits","Factores del coste de env\xEDo de LoloBuy: peso, volumen y l\xEDmites de ruta","LoloBuy Versandkosten: Gewicht, Volumen und Routenlimits","Facteurs du co\xFBt de livraison LoloBuy : poids, volume et limites de ligne","Fattori del costo di spedizione LoloBuy: peso, volume e limiti della linea"],["An early estimate can change when the packed dimensions, actual weight, destination, available routes and optional protection are known.","Una estimaci\xF3n inicial puede cambiar cuando se conocen las dimensiones embaladas, el peso real, el destino, las rutas disponibles y la protecci\xF3n opcional.","Eine fr\xFChe Sch\xE4tzung kann sich \xE4ndern, sobald Verpackungsma\xDFe, tats\xE4chliches Gewicht, Ziel, verf\xFCgbare Routen und optionaler Schutz bekannt sind.","Une estimation initiale peut changer lorsque les dimensions emball\xE9es, le poids r\xE9el, la destination, les lignes disponibles et les protections optionnelles sont connus.","Una stima iniziale pu\xF2 cambiare quando sono noti dimensioni imballate, peso reale, destinazione, linee disponibili e protezioni opzionali."],["Read the shipping article","Leer el art\xEDculo de env\xEDos","Versandartikel lesen","Lire l'article sur la livraison","Leggi l'articolo sulla spedizione"],["LoloBuy product finds: search terms, categories and variants","Productos LoloBuy: b\xFAsquedas, categor\xEDas y variantes","LoloBuy Produktfunde: Suchbegriffe, Kategorien und Varianten","Produits LoloBuy : recherches, cat\xE9gories et variantes","Prodotti LoloBuy: ricerche, categorie e varianti"],["Start with an exact product term when possible. Use categories for broad browsing, then open the matched item and confirm the option rather than relying on its thumbnail.","Empieza con un t\xE9rmino exacto cuando sea posible. Usa categor\xEDas para explorar, abre el art\xEDculo vinculado y confirma la opci\xF3n en lugar de confiar en la miniatura.","Beginne m\xF6glichst mit einem genauen Produktbegriff. Nutze Kategorien zum St\xF6bern, \xF6ffne dann den passenden Artikel und pr\xFCfe die Option statt nur dem Vorschaubild zu vertrauen.","Commencez si possible par un terme produit pr\xE9cis. Utilisez les cat\xE9gories pour parcourir, puis ouvrez l'article associ\xE9 et confirmez l'option au lieu de vous fier \xE0 la miniature.","Inizia quando possibile con un termine preciso. Usa le categorie per esplorare, poi apri l'articolo abbinato e conferma l'opzione invece di affidarti alla miniatura."],["Explore product research","Explorar la investigaci\xF3n de productos","Produktrecherche entdecken","Explorer la recherche produit","Esplora la ricerca prodotti"],["Editorial standard","Criterio editorial","Redaktioneller Standard","Norme \xE9ditoriale","Standard editoriale"],["Useful SEO content should help the reader make a decision","El contenido SEO \xFAtil debe ayudar al lector a decidir","N\xFCtzlicher SEO-Inhalt sollte bei Entscheidungen helfen","Un contenu SEO utile doit aider le lecteur \xE0 d\xE9cider","Un contenuto SEO utile deve aiutare a decidere"],["These articles separate product discovery from ordering, warehouse review and shipping. They avoid unverified promises about stock, product quality or final freight charges.","Estos art\xEDculos separan el descubrimiento del producto del pedido, la revisi\xF3n de almac\xE9n y el env\xEDo. Evitan promesas no verificadas sobre stock, calidad o costes finales.","Diese Artikel trennen Produktsuche von Bestellung, Lagerpr\xFCfung und Versand. Sie vermeiden unbelegte Versprechen zu Bestand, Qualit\xE4t oder endg\xFCltigen Frachtkosten.","Ces articles distinguent la d\xE9couverte, la commande, le contr\xF4le en entrep\xF4t et l'exp\xE9dition. Ils \xE9vitent les promesses non v\xE9rifi\xE9es sur le stock, la qualit\xE9 ou le co\xFBt final.","Questi articoli separano ricerca, ordine, controllo in magazzino e spedizione. Evitano promesse non verificate su disponibilit\xE0, qualit\xE0 o costi finali."],["The original product-page address.","La direcci\xF3n original de la p\xE1gina del producto.","Die urspr\xFCngliche Produktseiten-Adresse.","L'adresse d'origine de la page produit.","L'indirizzo originale della pagina prodotto."],["The exact size, color, batch or variant selected.","La talla, el color, el lote o la variante exactos.","Die genau gew\xE4hlte Gr\xF6\xDFe, Farbe, Charge oder Variante.","La taille, la couleur, le lot ou la variante exacte s\xE9lectionn\xE9e.","Taglia, colore, lotto o variante esatti selezionati."],["Any seller note that changes what will be sent.","Cualquier nota del vendedor que cambie lo que se enviar\xE1.","Jeder Verk\xE4uferhinweis, der den Lieferumfang ver\xE4ndert.","Toute note du vendeur qui modifie ce qui sera envoy\xE9.","Qualsiasi nota del venditore che cambi ci\xF2 che verr\xE0 spedito."],["The visible QC points you need to confirm.","Los puntos visibles de QC que necesitas confirmar.","Die sichtbaren QC-Punkte, die du best\xE4tigen musst.","Les points QC visibles \xE0 confirmer.","I punti QC visibili da confermare."],["The parcel restrictions that could affect your shipping route.","Las restricciones del paquete que pueden afectar a tu ruta de env\xEDo.","Paketbeschr\xE4nkungen, die deine Versandroute beeinflussen k\xF6nnen.","Les restrictions du colis pouvant affecter votre ligne d'exp\xE9dition.","Le restrizioni del pacco che possono influire sulla linea di spedizione."],["Eight practical answers","Ocho respuestas pr\xE1cticas","Acht praktische Antworten","Huit r\xE9ponses pratiques","Otto risposte pratiche"],["Know what happens before you click away","Entiende qu\xE9 ocurre antes de salir","Wissen, was vor dem Weiterklicken passiert","Sachez ce qui se passe avant de quitter la page","Scopri cosa succede prima di uscire"],["Product links go only to the matching main-site pages. Educational pages stay inside this site, and no navigation item sends traffic to another directory.","Los enlaces de producto llevan solo a las p\xE1ginas correspondientes del sitio principal. Las p\xE1ginas educativas permanecen aqu\xED y ning\xFAn elemento de navegaci\xF3n env\xEDa tr\xE1fico a otro directorio.","Produktlinks f\xFChren nur zu den passenden Seiten der Hauptseite. Informationsseiten bleiben auf dieser Website, und kein Navigationselement leitet zu einem anderen Verzeichnis.","Les liens produit m\xE8nent uniquement aux pages correspondantes du site principal. Les pages \xE9ducatives restent ici et aucun \xE9l\xE9ment de navigation ne renvoie vers un autre r\xE9pertoire.","I link prodotto portano solo alle pagine corrispondenti del sito principale. Le pagine informative restano qui e nessuna voce di navigazione invia traffico ad altre directory."],["Still looking for an item?","\xBFSigues buscando un art\xEDculo?","Noch auf Artikelsuche?","Vous cherchez encore un article ?","Cerchi ancora un articolo?"],["Search the main catalog with the exact product term","Busca en el cat\xE1logo principal con el t\xE9rmino exacto","Hauptkatalog mit dem genauen Produktbegriff durchsuchen","Recherchez dans le catalogue principal avec le terme exact","Cerca nel catalogo principale con il termine esatto"],["Find the matching item","Encuentra el art\xEDculo correspondiente","Passenden Artikel finden","Trouvez l'article correspondant","Trova l'articolo corrispondente"],["Search by keyword, choose a category or open a product card whose image and main-site detail page are already paired.","Busca por palabra clave, elige una categor\xEDa o abre una tarjeta cuya imagen ya est\xE9 vinculada a su p\xE1gina de detalle del sitio principal.","Suche per Stichwort, w\xE4hle eine Kategorie oder \xF6ffne eine Produktkarte, deren Bild bereits mit der passenden Detailseite der Hauptseite verkn\xFCpft ist.","Recherchez par mot-cl\xE9, choisissez une cat\xE9gorie ou ouvrez une fiche dont l'image est d\xE9j\xE0 associ\xE9e \xE0 la page d\xE9taill\xE9e du site principal.","Cerca per parola chiave, scegli una categoria o apri una scheda la cui immagine \xE8 gi\xE0 abbinata alla pagina dettagliata del sito principale."],["Review the listing","Revisa el anuncio","Angebot pr\xFCfen","V\xE9rifiez l'annonce","Controlla l'inserzione"],["Confirm the seller page, selected option, price, size, color and domestic delivery details before submitting anything.","Confirma la p\xE1gina del vendedor, la opci\xF3n elegida, el precio, la talla, el color y los datos de entrega nacional antes de enviar nada.","Pr\xFCfe Verk\xE4uferseite, gew\xE4hlte Option, Preis, Gr\xF6\xDFe, Farbe und Inlandsversand, bevor du etwas \xFCbermittelst.","Confirmez la page du vendeur, l'option choisie, le prix, la taille, la couleur et la livraison nationale avant toute soumission.","Verifica pagina del venditore, opzione selezionata, prezzo, taglia, colore e consegna nazionale prima di inviare."],["Preserve the source","Conserva el origen","Quelle bewahren","Conservez la source","Conserva la fonte"],["Keep the original marketplace address and any useful variant notes so the requested item remains unambiguous.","Conserva la direcci\xF3n original del mercado y las notas \xFAtiles sobre la variante para que el art\xEDculo solicitado siga siendo inequ\xEDvoco.","Bewahre die urspr\xFCngliche Marktplatz-Adresse und hilfreiche Variantenhinweise auf, damit der gew\xFCnschte Artikel eindeutig bleibt.","Conservez l'adresse d'origine de la marketplace et les notes utiles sur la variante afin que l'article demand\xE9 reste sans ambigu\xEFt\xE9.","Conserva l'indirizzo originale del marketplace e le note utili sulla variante, cos\xEC l'articolo richiesto resta chiaro."],["Inspect before shipping","Inspecciona antes del env\xEDo","Vor dem Versand pr\xFCfen","Inspectez avant l'exp\xE9dition","Controlla prima della spedizione"],["Compare the warehouse photos with the order record and only plan the parcel after checking visible condition and route needs.","Compara las fotos de almac\xE9n con el pedido y planifica el paquete solo despu\xE9s de comprobar el estado visible y las necesidades de ruta.","Vergleiche Lagerfotos mit der Bestellung und plane das Paket erst nach Pr\xFCfung des sichtbaren Zustands und der Routenanforderungen.","Comparez les photos d'entrep\xF4t \xE0 la commande et ne planifiez le colis qu'apr\xE8s avoir v\xE9rifi\xE9 l'\xE9tat visible et les besoins de la ligne.","Confronta le foto di magazzino con l'ordine e pianifica il pacco solo dopo aver verificato condizioni visibili ed esigenze della linea."],["Start here","Empieza aqu\xED","Hier beginnen","Commencez ici","Inizia qui"],["Use the exact keyword you already have in mind","Usa la palabra exacta que ya tienes en mente","Den genauen Suchbegriff verwenden","Utilisez le mot-cl\xE9 exact que vous avez en t\xEAte","Usa la parola chiave esatta che hai in mente"],["Research-backed LoloBuy guides for real buying decisions","Gu\xEDas LoloBuy documentadas para decisiones de compra reales","Fundierte LoloBuy-Ratgeber f\xFCr echte Kaufentscheidungen","Guides LoloBuy document\xE9s pour de vraies d\xE9cisions d'achat","Guide LoloBuy documentate per decisioni di acquisto reali"],["Use focused long-form guides for product discovery, listing checks, warehouse-photo review and parcel planning. Every claim is either verifiable, clearly qualified or presented as an example.","Usa gu\xEDas detalladas para descubrir productos, revisar anuncios, evaluar fotos de almac\xE9n y planificar paquetes. Cada afirmaci\xF3n es verificable, est\xE1 claramente matizada o se presenta como ejemplo.","Nutze ausf\xFChrliche Ratgeber f\xFCr Produktsuche, Angebotspr\xFCfung, Lagerfoto-Kontrolle und Paketplanung. Jede Aussage ist \xFCberpr\xFCfbar, klar eingeordnet oder als Beispiel gekennzeichnet.","Utilisez des guides d\xE9taill\xE9s pour trouver des produits, v\xE9rifier les annonces, examiner les photos d'entrep\xF4t et pr\xE9parer les colis. Chaque affirmation est v\xE9rifiable, clairement nuanc\xE9e ou pr\xE9sent\xE9e comme exemple.","Usa guide approfondite per trovare prodotti, verificare inserzioni, esaminare foto di magazzino e pianificare i pacchi. Ogni affermazione \xE8 verificabile, chiaramente qualificata o presentata come esempio."],["Start with the buying journey","Empieza por el proceso de compra","Mit dem Kaufprozess beginnen","Commencez par le parcours d'achat","Inizia dal percorso di acquisto"],["Discovery first. QC second. Shipping third.","Primero el producto. Despu\xE9s el QC. Por \xFAltimo el env\xEDo.","Zuerst die Suche. Dann QC. Danach der Versand.","D'abord la recherche. Ensuite le QC. Enfin l'exp\xE9dition.","Prima la ricerca. Poi il QC. Infine la spedizione."],["Find and document the exact product before discussing warehouse quality or parcel cost.","Encuentra y documenta el producto exacto antes de valorar la calidad en almac\xE9n o el coste del paquete.","Finde und dokumentiere das genaue Produkt, bevor du Lagerqualit\xE4t oder Paketkosten bewertest.","Trouvez et documentez le produit exact avant d'\xE9valuer la qualit\xE9 en entrep\xF4t ou le co\xFBt du colis.","Trova e documenta il prodotto esatto prima di valutare la qualit\xE0 in magazzino o il costo del pacco."],["Compare the warehouse arrival with the saved order record and the selected option.","Compara lo recibido en almac\xE9n con el pedido guardado y la opci\xF3n seleccionada.","Vergleiche den Lagereingang mit der gespeicherten Bestellung und der gew\xE4hlten Option.","Comparez l'arriv\xE9e en entrep\xF4t avec la commande enregistr\xE9e et l'option choisie.","Confronta l'arrivo in magazzino con l'ordine salvato e l'opzione selezionata."],["Build the international parcel only after accepted items and realistic packed data are available.","Prepara el paquete internacional solo cuando los art\xEDculos est\xE9n aceptados y dispongas de datos reales del embalaje.","Stelle das internationale Paket erst zusammen, wenn die Artikel akzeptiert sind und realistische Packdaten vorliegen.","Pr\xE9parez le colis international seulement lorsque les articles sont accept\xE9s et que des donn\xE9es d'emballage r\xE9alistes sont disponibles.","Prepara il pacco internazionale solo dopo aver accettato gli articoli e ottenuto dati realistici dell'imballaggio."],["Product discovery guide","Gu\xEDa de descubrimiento de productos","Ratgeber zur Produktsuche","Guide de recherche de produits","Guida alla ricerca dei prodotti"],["How to Use a LoloBuy Spreadsheet Without Losing the Original Product Context","C\xF3mo usar una hoja LoloBuy sin perder el contexto original del producto","So nutzt du ein LoloBuy Spreadsheet, ohne den urspr\xFCnglichen Produktkontext zu verlieren","Comment utiliser un tableur LoloBuy sans perdre le contexte d'origine du produit","Come usare un foglio LoloBuy senza perdere il contesto originale del prodotto"],["A practical LoloBuy spreadsheet guide covering source links, variants, seller notes, W2C terminology and the checks to make before ordering.","Gu\xEDa pr\xE1ctica de la hoja LoloBuy sobre enlaces de origen, variantes, notas del vendedor, t\xE9rminos W2C y comprobaciones previas al pedido.","Praktischer LoloBuy-Spreadsheet-Ratgeber zu Quelllinks, Varianten, Verk\xE4uferhinweisen, W2C-Begriffen und Pr\xFCfungen vor der Bestellung.","Guide pratique du tableur LoloBuy sur les liens source, variantes, notes vendeur, termes W2C et v\xE9rifications avant commande.","Guida pratica al foglio LoloBuy su link originali, varianti, note del venditore, termini W2C e controlli prima dell'ordine."],["Warehouse inspection guide","Gu\xEDa de inspecci\xF3n de almac\xE9n","Ratgeber zur Lagerpr\xFCfung","Guide de contr\xF4le en entrep\xF4t","Guida al controllo in magazzino"],["LoloBuy QC Photos: A Warehouse Inspection Guide That Avoids Guesswork","Fotos QC de LoloBuy: gu\xEDa de inspecci\xF3n de almac\xE9n sin suposiciones","LoloBuy QC-Fotos: Lagerpr\xFCfung ohne R\xE4tselraten","Photos QC LoloBuy : guide de contr\xF4le en entrep\xF4t sans suppositions","Foto QC LoloBuy: guida al controllo in magazzino senza supposizioni"],["Learn how to review LoloBuy QC photos for identity, variants, measurements and visible condition, plus what warehouse pictures cannot prove.","Aprende a revisar fotos QC de LoloBuy para comprobar identidad, variantes, medidas y estado visible, adem\xE1s de lo que las im\xE1genes de almac\xE9n no pueden demostrar.","Lerne, LoloBuy-QC-Fotos auf Identit\xE4t, Varianten, Ma\xDFe und sichtbaren Zustand zu pr\xFCfen und ihre Grenzen zu verstehen.","Apprenez \xE0 v\xE9rifier les photos QC LoloBuy pour l'identit\xE9, les variantes, les mesures et l'\xE9tat visible, ainsi que leurs limites.","Scopri come esaminare le foto QC LoloBuy per identit\xE0, varianti, misure e condizioni visibili, oltre ai limiti delle immagini di magazzino."],["International parcel guide","Gu\xEDa de paquetes internacionales","Ratgeber f\xFCr internationale Pakete","Guide du colis international","Guida al pacco internazionale"],["LoloBuy Shipping Cost Guide: Weight, Parcel Size, Routes and Consolidation","Gu\xEDa de costes de env\xEDo LoloBuy: peso, tama\xF1o, rutas y consolidaci\xF3n","LoloBuy Versandkosten: Gewicht, Paketgr\xF6\xDFe, Routen und Konsolidierung","Guide des co\xFBts de livraison LoloBuy : poids, dimensions, lignes et consolidation","Guida ai costi di spedizione LoloBuy: peso, dimensioni, linee e consolidamento"],["Understand LoloBuy shipping cost variables, actual versus volumetric weight, consolidation, packaging, route restrictions and realistic parcel estimates.","Comprende las variables del coste de env\xEDo LoloBuy, el peso real y volum\xE9trico, la consolidaci\xF3n, el embalaje, las restricciones y las estimaciones realistas.","Verstehe LoloBuy-Versandkosten, tats\xE4chliches und volumetrisches Gewicht, Konsolidierung, Verpackung, Routenlimits und realistische Sch\xE4tzungen.","Comprenez les variables du co\xFBt de livraison LoloBuy, le poids r\xE9el et volum\xE9trique, la consolidation, l'emballage, les restrictions et les estimations r\xE9alistes.","Comprendi le variabili dei costi LoloBuy, il peso reale e volumetrico, il consolidamento, l'imballaggio, i limiti delle linee e le stime realistiche."],["Primary topic","Tema principal","Hauptthema","Sujet principal","Argomento principale"],["Length","Longitud","L\xE4nge","Longueur","Lunghezza"],["words","palabras","W\xF6rter","mots","parole"],["Fact checked","Verificado","Fakten gepr\xFCft","V\xE9rifi\xE9","Verificato"],["28 July 2026","28 de julio de 2026","28. Juli 2026","28 juillet 2026","28 luglio 2026"],["Read the complete guide","Leer la gu\xEDa completa","Vollst\xE4ndigen Ratgeber lesen","Lire le guide complet","Leggi la guida completa"],["Facts, examples and uncertainty stay separate","Los hechos, los ejemplos y la incertidumbre se mantienen separados","Fakten, Beispiele und Unsicherheit bleiben getrennt","Les faits, les exemples et les incertitudes restent distincts","Fatti, esempi e incertezza restano separati"],["Official public statements are dated and described as statements, not independent guarantees.","Las declaraciones p\xFAblicas oficiales llevan fecha y se presentan como declaraciones, no como garant\xEDas independientes.","Offizielle \xF6ffentliche Aussagen sind datiert und werden nicht als unabh\xE4ngige Garantien dargestellt.","Les d\xE9clarations publiques officielles sont dat\xE9es et pr\xE9sent\xE9es comme telles, non comme des garanties ind\xE9pendantes.","Le dichiarazioni pubbliche ufficiali sono datate e presentate come tali, non come garanzie indipendenti."],["Illustrative calculations are labeled and never presented as a fixed LoloBuy fee.","Los c\xE1lculos ilustrativos se identifican y nunca se presentan como una tarifa fija de LoloBuy.","Beispielrechnungen sind gekennzeichnet und werden nie als feste LoloBuy-Geb\xFChr dargestellt.","Les calculs illustratifs sont signal\xE9s et ne sont jamais pr\xE9sent\xE9s comme des frais LoloBuy fixes.","I calcoli illustrativi sono segnalati e non vengono mai presentati come una tariffa fissa LoloBuy."],["Individual customer reports are identified as individual experiences, not manufactured ratings.","Los testimonios individuales se identifican como experiencias personales, no como valoraciones inventadas.","Einzelne Kundenberichte werden als individuelle Erfahrungen gekennzeichnet, nicht als erfundene Bewertungen.","Les t\xE9moignages individuels sont pr\xE9sent\xE9s comme des exp\xE9riences personnelles, non comme des notes fabriqu\xE9es.","Le testimonianze individuali sono indicate come esperienze personali, non come valutazioni inventate."],["Product availability, seller terms, services and shipping routes are treated as changeable live information.","La disponibilidad, las condiciones del vendedor, los servicios y las rutas se tratan como informaci\xF3n din\xE1mica que puede cambiar.","Verf\xFCgbarkeit, Verk\xE4uferbedingungen, Dienste und Versandrouten werden als ver\xE4nderliche Live-Informationen behandelt.","La disponibilit\xE9, les conditions vendeur, les services et les lignes sont trait\xE9s comme des informations susceptibles de changer.","Disponibilit\xE0, condizioni del venditore, servizi e linee di spedizione sono trattati come informazioni dinamiche soggette a cambiamenti."]],p=[["Independent product-finding guide","Gu\xEDa independiente para encontrar productos","Unabh\xE4ngiger Ratgeber zur Produktsuche","Guide ind\xE9pendant de recherche de produits","Guida indipendente alla ricerca dei prodotti"],["LoloBuy Spreadsheet 2026: Matched Product Finds & Buying Guides","Hoja LoloBuy 2026: productos vinculados y gu\xEDas de compra","LoloBuy Spreadsheet 2026: passende Produktfunde und Kaufratgeber","Tableur LoloBuy 2026 : produits associ\xE9s et guides d'achat","Foglio LoloBuy 2026: prodotti abbinati e guide all'acquisto"],["Find the item.","Encuentra el art\xEDculo.","Artikel finden.","Trouvez l'article.","Trova l'articolo."],["Check the details.","Comprueba los detalles.","Details pr\xFCfen.","V\xE9rifiez les d\xE9tails.","Controlla i dettagli."],["Buy with context.","Compra con informaci\xF3n.","Informiert kaufen.","Achetez en connaissance de cause.","Acquista con consapevolezza."],["Searchable China shopping finds and practical LoloBuy guides, built to help you compare a listing before you order.","Productos de compra en China y gu\xEDas pr\xE1cticas de LoloBuy para ayudarte a comparar un anuncio antes de pedir.","Durchsuchbare China-Produkte und praktische LoloBuy-Ratgeber, mit denen du ein Angebot vor der Bestellung vergleichen kannst.","Produits chinois consultables et guides LoloBuy pratiques pour comparer une annonce avant de commander.","Prodotti cinesi ricercabili e guide pratiche LoloBuy per confrontare un'inserzione prima dell'ordine."],["Browse product finds","Ver productos encontrados","Produktfunde ansehen","Voir les produits trouv\xE9s","Vedi i prodotti trovati"],["How it works","C\xF3mo funciona","So funktioniert es","Comment \xE7a marche","Come funziona"],["Independent guide \xB7 Product images matched to their destination pages","Gu\xEDa independiente \xB7 Im\xE1genes de producto vinculadas a sus p\xE1ginas de destino","Unabh\xE4ngiger Ratgeber \xB7 Produktbilder mit ihren Zielseiten verkn\xFCpft","Guide ind\xE9pendant \xB7 Images produit associ\xE9es \xE0 leurs pages de destination","Guida indipendente \xB7 Immagini prodotto abbinate alle pagine di destinazione"],["SOURCE MATCHED","ORIGEN VINCULADO","QUELLE ZUGEORDNET","SOURCE ASSOCI\xC9E","FONTE ABBINATA"],["PRODUCT SOURCE","ORIGEN DEL PRODUCTO","PRODUKTQUELLE","SOURCE DU PRODUIT","FONTE DEL PRODOTTO"],["Image and page paired","Imagen y p\xE1gina vinculadas","Bild und Seite verkn\xFCpft","Image et page associ\xE9es","Immagine e pagina abbinate"],["Checked 29 Jul 2026","Revisado el 29 jul 2026","Gepr\xFCft am 29. Juli 2026","V\xE9rifi\xE9 le 29 juil. 2026","Verificato il 29 lug 2026"],["BEFORE ORDERING","ANTES DE PEDIR","VOR DER BESTELLUNG","AVANT DE COMMANDER","PRIMA DI ORDINARE"],["Review size and variant","Revisa la talla y la variante","Gr\xF6\xDFe und Variante pr\xFCfen","V\xE9rifiez la taille et la variante","Controlla taglia e variante"],["Seller details may change","Los datos del vendedor pueden cambiar","Verk\xE4uferangaben k\xF6nnen sich \xE4ndern","Les informations du vendeur peuvent changer","I dati del venditore possono cambiare"],["Current catalog sample","Muestra actual del cat\xE1logo","Aktuelle Katalogauswahl","Extrait actuel du catalogue","Esempio attuale del catalogo"],["Catalog entries, correctly paired","Entradas del cat\xE1logo correctamente vinculadas","Katalogeintr\xE4ge korrekt verkn\xFCpft","Entr\xE9es du catalogue correctement associ\xE9es","Voci del catalogo abbinate correttamente"],["Every card below uses the first product image from its matching destination page. Clicking the image, title or button opens that exact product\u2014not a generic category or duplicated link.","Cada tarjeta usa la primera imagen de la p\xE1gina de destino correspondiente. Al pulsar la imagen, el t\xEDtulo o el bot\xF3n se abre ese producto exacto, no una categor\xEDa gen\xE9rica ni un enlace duplicado.","Jede Karte verwendet das erste Produktbild der passenden Zielseite. Ein Klick auf Bild, Titel oder Schaltfl\xE4che \xF6ffnet genau dieses Produkt \u2013 keine allgemeine Kategorie und keinen doppelten Link.","Chaque fiche utilise la premi\xE8re image de sa page de destination correspondante. Un clic sur l'image, le titre ou le bouton ouvre ce produit pr\xE9cis, et non une cat\xE9gorie g\xE9n\xE9rique ou un lien dupliqu\xE9.","Ogni scheda usa la prima immagine della pagina di destinazione corrispondente. Facendo clic su immagine, titolo o pulsante si apre quel prodotto preciso, non una categoria generica o un link duplicato."],["View the full product catalog","Ver el cat\xE1logo completo","Vollst\xE4ndigen Produktkatalog ansehen","Voir le catalogue complet","Vedi il catalogo completo"],["Availability, variants and seller details can change. Check the destination page again before ordering.","La disponibilidad, las variantes y los datos del vendedor pueden cambiar. Comprueba de nuevo la p\xE1gina de destino antes de pedir.","Verf\xFCgbarkeit, Varianten und Verk\xE4uferangaben k\xF6nnen sich \xE4ndern. Pr\xFCfe die Zielseite vor der Bestellung erneut.","La disponibilit\xE9, les variantes et les informations du vendeur peuvent changer. V\xE9rifiez de nouveau la page de destination avant de commander.","Disponibilit\xE0, varianti e dati del venditore possono cambiare. Ricontrolla la pagina di destinazione prima di ordinare."],["Browse by intent","Explorar seg\xFAn la intenci\xF3n","Nach Bedarf st\xF6bern","Parcourir selon le besoin","Esplora per obiettivo"],["Start with a category","Empieza por una categor\xEDa","Mit einer Kategorie beginnen","Commencez par une cat\xE9gorie","Inizia da una categoria"],["Use a focused category when you know the item type, or use the search box above for a specific product name.","Usa una categor\xEDa concreta si conoces el tipo de art\xEDculo, o utiliza el buscador superior para un nombre de producto espec\xEDfico.","Nutze eine passende Kategorie, wenn du den Artikeltyp kennst, oder das Suchfeld oben f\xFCr einen bestimmten Produktnamen.","Utilisez une cat\xE9gorie pr\xE9cise si vous connaissez le type d'article, ou le champ de recherche ci-dessus pour un nom de produit pr\xE9cis.","Usa una categoria specifica se conosci il tipo di articolo, oppure il campo di ricerca in alto per un nome preciso."],["From find to warehouse","Del hallazgo al almac\xE9n","Vom Fund ins Lager","De la trouvaille \xE0 l'entrep\xF4t","Dalla ricerca al magazzino"],["How to use these product finds","C\xF3mo usar estos productos encontrados","So nutzt du diese Produktfunde","Comment utiliser cette s\xE9lection de produits","Come usare questi prodotti trovati"],["A spreadsheet is the discovery layer. LoloBuy is the purchasing and forwarding layer. Keep those roles separate as you review an item.","Una hoja de c\xE1lculo sirve para descubrir productos. LoloBuy se encarga de la compra y el reenv\xEDo. Mant\xE9n separadas esas funciones al revisar un art\xEDculo.","Ein Spreadsheet dient der Produktsuche. LoloBuy \xFCbernimmt Einkauf und Weiterleitung. Halte diese Rollen bei der Artikelpr\xFCfung auseinander.","Une feuille de calcul sert \xE0 d\xE9couvrir les produits. LoloBuy prend en charge l'achat et l'exp\xE9dition. Gardez ces r\xF4les distincts lorsque vous examinez un article.","Un foglio serve a scoprire i prodotti. LoloBuy gestisce acquisto e inoltro. Mantieni separati questi ruoli mentre valuti un articolo."],["Open the matching item","Abre el art\xEDculo correspondiente","Passenden Artikel \xF6ffnen","Ouvrez l'article correspondant","Apri l'articolo corrispondente"],["Choose a product card. Its image and link are paired to the same item page, so you can inspect the source listing without guessing which product it represents.","Elige una tarjeta de producto. Su imagen y su enlace corresponden a la misma p\xE1gina, para que puedas revisar el anuncio original sin adivinar qu\xE9 producto representa.","W\xE4hle eine Produktkarte. Bild und Link geh\xF6ren zur selben Artikelseite, sodass du das Ursprungsangebot pr\xFCfen kannst, ohne das Produkt erraten zu m\xFCssen.","Choisissez une fiche produit. Son image et son lien correspondent \xE0 la m\xEAme page, afin de v\xE9rifier l'annonce source sans deviner quel produit elle repr\xE9sente.","Scegli una scheda prodotto. Immagine e link corrispondono alla stessa pagina, cos\xEC puoi esaminare l'inserzione originale senza indovinare il prodotto."],["Review the source link","Revisa el enlace de origen","Quelllink pr\xFCfen","V\xE9rifiez le lien source","Controlla il link originale"],["Confirm the seller page, selected variant, size, color, current price and domestic delivery terms. A thumbnail alone is not enough for a purchase decision.","Confirma la p\xE1gina del vendedor, la variante, la talla, el color, el precio actual y las condiciones de entrega nacional. Una miniatura no basta para decidir una compra.","Pr\xFCfe Verk\xE4uferseite, gew\xE4hlte Variante, Gr\xF6\xDFe, Farbe, aktuellen Preis und Inlandsversand. Ein Vorschaubild allein reicht f\xFCr eine Kaufentscheidung nicht aus.","Confirmez la page du vendeur, la variante choisie, la taille, la couleur, le prix actuel et les conditions de livraison nationale. Une miniature ne suffit pas pour d\xE9cider d'un achat.","Verifica pagina del venditore, variante selezionata, taglia, colore, prezzo attuale e consegna nazionale. Una miniatura da sola non basta per decidere l'acquisto."],["Submit the product to LoloBuy","Env\xEDa el producto a LoloBuy","Produkt an LoloBuy \xFCbermitteln","Soumettez le produit \xE0 LoloBuy","Invia il prodotto a LoloBuy"],["Copy the original marketplace link and paste it into LoloBuy. If automatic parsing is unavailable, the official site also exposes a manual-order path for entering item details.","Copia el enlace original del mercado y p\xE9galo en LoloBuy. Si el an\xE1lisis autom\xE1tico no est\xE1 disponible, el sitio oficial tambi\xE9n ofrece una v\xEDa de pedido manual para introducir los datos del art\xEDculo.","Kopiere den urspr\xFCnglichen Marktplatz-Link und f\xFCge ihn bei LoloBuy ein. Falls die automatische Erkennung nicht verf\xFCgbar ist, bietet die offizielle Website auch eine manuelle Bestellung zur Eingabe der Artikeldaten.","Copiez le lien d'origine de la marketplace et collez-le dans LoloBuy. Si l'analyse automatique n'est pas disponible, le site officiel propose aussi une commande manuelle pour saisir les informations de l'article.","Copia il link originale del marketplace e incollalo in LoloBuy. Se l'analisi automatica non \xE8 disponibile, il sito ufficiale offre anche un ordine manuale per inserire i dati dell'articolo."],["Inspect, pack and ship","Inspecciona, embala y env\xEDa","Pr\xFCfen, packen und versenden","Inspectez, emballez et exp\xE9diez","Ispeziona, imballa e spedisci"],["After the seller sends the item to the warehouse, review the warehouse photos and item status. Submit a parcel only after choosing a suitable route and checking the final parcel setup.","Cuando el vendedor env\xEDe el art\xEDculo al almac\xE9n, revisa las fotos y su estado. Env\xEDa el paquete solo despu\xE9s de elegir una ruta adecuada y comprobar la configuraci\xF3n final.","Nachdem der Verk\xE4ufer den Artikel ans Lager gesendet hat, pr\xFCfe Lagerfotos und Artikelstatus. Reiche das Paket erst ein, nachdem du eine geeignete Route und die endg\xFCltige Paketzusammenstellung gepr\xFCft hast.","Apr\xE8s l'envoi de l'article \xE0 l'entrep\xF4t, v\xE9rifiez les photos et son statut. Soumettez le colis seulement apr\xE8s avoir choisi une ligne adapt\xE9e et contr\xF4l\xE9 sa configuration finale.","Dopo l'invio dell'articolo al magazzino, controlla foto e stato. Invia il pacco solo dopo aver scelto una linea adatta e verificato la configurazione finale."],["QC CHECKLIST EXAMPLE","EJEMPLO DE LISTA QC","BEISPIEL EINER QC-CHECKLISTE","EXEMPLE DE LISTE QC","ESEMPIO DI CHECKLIST QC"],["3 POINT REVIEW","REVISI\xD3N DE 3 PUNTOS","3-PUNKTE-PR\xDCFUNG","V\xC9RIFICATION EN 3 POINTS","CONTROLLO IN 3 PUNTI"],["Correct variant","Variante correcta","Richtige Variante","Variante correcte","Variante corretta"],["Size label visible","Etiqueta de talla visible","Gr\xF6\xDFenetikett sichtbar","\xC9tiquette de taille visible","Etichetta taglia visibile"],["Front and back reviewed","Parte delantera y trasera revisadas","Vorder- und R\xFCckseite gepr\xFCft","Avant et dos v\xE9rifi\xE9s","Fronte e retro controllati"],["Practical LoloBuy QC guide","Gu\xEDa pr\xE1ctica de QC de LoloBuy","Praktischer LoloBuy QC-Ratgeber","Guide QC pratique pour LoloBuy","Guida pratica QC per LoloBuy"],["Use warehouse photos to answer specific questions","Usa las fotos del almac\xE9n para responder preguntas concretas","Lagerfotos f\xFCr konkrete Fragen nutzen","Utilisez les photos d'entrep\xF4t pour r\xE9pondre \xE0 des questions pr\xE9cises","Usa le foto di magazzino per rispondere a domande specifiche"],["LoloBuy's current site describes quality-inspection warehousing and product-photo services. Treat those images as a decision aid: compare what arrived with the variant you ordered, rather than judging an item from one flattering angle.","El sitio actual de LoloBuy describe servicios de almacenamiento con inspecci\xF3n de calidad y fotograf\xEDas de productos. Usa esas im\xE1genes como ayuda para decidir: compara lo recibido con la variante pedida, en vez de juzgar el art\xEDculo desde un \xFAnico \xE1ngulo favorecedor.","Die aktuelle LoloBuy-Website beschreibt Lagerung mit Qualit\xE4tspr\xFCfung und Produktfotos. Nutze diese Bilder als Entscheidungshilfe: Vergleiche den eingetroffenen Artikel mit der bestellten Variante, statt ihn nach einer einzigen g\xFCnstigen Aufnahme zu beurteilen.","Le site actuel de LoloBuy d\xE9crit des services d'entreposage avec contr\xF4le qualit\xE9 et photos produit. Utilisez ces images comme aide \xE0 la d\xE9cision : comparez l'article re\xE7u \xE0 la variante command\xE9e plut\xF4t que de le juger sur un seul angle avantageux.","Il sito attuale di LoloBuy descrive servizi di magazzino con controllo qualit\xE0 e foto prodotto. Usa le immagini come supporto decisionale: confronta ci\xF2 che \xE8 arrivato con la variante ordinata, invece di giudicare da una sola angolazione favorevole."],["Match the color, size label and selected option to your order record.","Compara el color, la etiqueta de talla y la opci\xF3n elegida con el registro del pedido.","Gleiche Farbe, Gr\xF6\xDFenetikett und gew\xE4hlte Option mit deiner Bestellung ab.","Comparez la couleur, l'\xE9tiquette de taille et l'option choisie avec votre commande.","Confronta colore, etichetta della taglia e opzione selezionata con l'ordine."],["Look for obvious damage, marks, missing parts or a visibly different item.","Busca da\xF1os evidentes, marcas, piezas faltantes o un art\xEDculo claramente diferente.","Achte auf offensichtliche Sch\xE4den, Spuren, fehlende Teile oder einen sichtbar anderen Artikel.","Recherchez des dommages \xE9vidents, des marques, des pi\xE8ces manquantes ou un article visiblement diff\xE9rent.","Cerca danni evidenti, segni, parti mancanti o un articolo visibilmente diverso."],["Use detailed-photo options when one area cannot be evaluated from the standard warehouse views.","Usa opciones de fotos detalladas cuando una zona no pueda evaluarse con las vistas est\xE1ndar del almac\xE9n.","Nutze Detailfoto-Optionen, wenn ein Bereich auf den Standard-Lagerbildern nicht beurteilt werden kann.","Utilisez les options de photos d\xE9taill\xE9es lorsqu'une zone ne peut pas \xEAtre \xE9valu\xE9e sur les vues standard de l'entrep\xF4t.","Usa le opzioni per foto dettagliate quando un'area non \xE8 valutabile dalle viste standard del magazzino."],["QC photos reduce uncertainty, but they do not guarantee fit, material composition, authenticity or long-term performance.","Las fotos de QC reducen la incertidumbre, pero no garantizan el ajuste, la composici\xF3n del material, la autenticidad ni el rendimiento a largo plazo.","QC-Fotos verringern Unsicherheit, garantieren aber weder Passform, Materialzusammensetzung, Echtheit noch langfristige Leistung.","Les photos QC r\xE9duisent l'incertitude, mais ne garantissent ni la coupe, ni la composition, l'authenticit\xE9 ou la performance \xE0 long terme.","Le foto QC riducono l'incertezza, ma non garantiscono vestibilit\xE0, composizione, autenticit\xE0 o prestazioni nel tempo."],["Shipping without guesswork","Env\xEDos sin conjeturas","Versand ohne R\xE4tselraten","Exp\xE9dition sans approximation","Spedizione senza supposizioni"],["Plan the parcel before you pay international freight","Planifica el paquete antes de pagar el env\xEDo internacional","Paket planen, bevor du den internationalen Versand bezahlst","Planifiez le colis avant de payer le transport international","Pianifica il pacco prima di pagare la spedizione internazionale"],["LoloBuy's official interface includes a freight estimate, warehouse, parcel submission and rehearsal flow. The cheapest product does not always create the cheapest parcel: destination, route limits, actual weight, parcel dimensions and added packing can all affect the chargeable result.","La interfaz oficial de LoloBuy incluye estimaci\xF3n de transporte, almac\xE9n, env\xEDo de paquetes y ensayo de embalaje. El producto m\xE1s barato no siempre genera el paquete m\xE1s barato: destino, l\xEDmites de ruta, peso real, dimensiones y embalaje a\xF1adido pueden afectar al coste facturable.","Die offizielle LoloBuy-Oberfl\xE4che umfasst Frachtsch\xE4tzung, Lager, Paketeinreichung und Probeverpackung. Das g\xFCnstigste Produkt ergibt nicht immer das g\xFCnstigste Paket: Ziel, Routenlimits, tats\xE4chliches Gewicht, Ma\xDFe und zus\xE4tzliche Verpackung k\xF6nnen den berechneten Preis beeinflussen.","L'interface officielle de LoloBuy comprend une estimation de transport, l'entrep\xF4t, la soumission de colis et la simulation d'emballage. Le produit le moins cher ne donne pas toujours le colis le moins cher : destination, limites de ligne, poids r\xE9el, dimensions et emballage suppl\xE9mentaire influencent le montant facturable.","L'interfaccia ufficiale di LoloBuy include stima del trasporto, magazzino, invio del pacco e prova d'imballaggio. Il prodotto pi\xF9 economico non crea sempre il pacco meno costoso: destinazione, limiti della linea, peso reale, dimensioni e imballaggio aggiuntivo possono incidere sul costo."],["Read the complete shipping guide","Leer la gu\xEDa completa de env\xEDos","Vollst\xE4ndigen Versandratgeber lesen","Lire le guide de livraison complet","Leggi la guida completa alla spedizione"],["WEIGHT","PESO","GEWICHT","POIDS","PESO"],["Actual vs. volumetric","Real frente a volum\xE9trico","Tats\xE4chlich vs. volumetrisch","R\xE9el ou volum\xE9trique","Reale o volumetrico"],["Bulky, light goods may be billed by volume on routes that use dimensional weight. Packaging can therefore matter as much as the scale reading.","Los art\xEDculos voluminosos y ligeros pueden cobrarse por volumen en rutas que usan peso dimensional. Por eso, el embalaje puede importar tanto como la lectura de la b\xE1scula.","Gro\xDFe, leichte Waren k\xF6nnen auf Routen mit Volumengewicht nach Abmessungen berechnet werden. Die Verpackung kann daher ebenso wichtig sein wie das Waagengewicht.","Les articles volumineux et l\xE9gers peuvent \xEAtre factur\xE9s au volume sur les lignes utilisant le poids volum\xE9trique. L'emballage peut donc compter autant que le poids sur la balance.","Articoli voluminosi e leggeri possono essere addebitati a volume sulle linee che usano il peso volumetrico. L'imballaggio pu\xF2 quindi contare quanto il peso sulla bilancia."],["ROUTE","RUTA","ROUTE","LIGNE","LINEA"],["Limits differ","Los l\xEDmites var\xEDan","Limits unterscheiden sich","Les limites varient","I limiti variano"],["Each route can have its own destination, weight and item restrictions. An unavailable route is a planning constraint, not a checkout error to ignore.","Cada ruta puede tener sus propias restricciones de destino, peso y art\xEDculos. Una ruta no disponible es una limitaci\xF3n de planificaci\xF3n, no un error de pago que deba ignorarse.","Jede Route kann eigene Ziel-, Gewichts- und Artikelbeschr\xE4nkungen haben. Eine nicht verf\xFCgbare Route ist eine Planungsgrenze, kein zu ignorierender Checkout-Fehler.","Chaque ligne peut avoir ses propres restrictions de destination, de poids et d'articles. Une ligne indisponible est une contrainte de planification, pas une erreur \xE0 ignorer.","Ogni linea pu\xF2 avere proprie restrizioni su destinazione, peso e articoli. Una linea non disponibile \xE8 un vincolo di pianificazione, non un errore da ignorare."],["PARCEL","PAQUETE","PAKET","COLIS","PACCO"],["Consolidate carefully","Consolida con cuidado","Sorgf\xE4ltig zusammenlegen","Consolidez avec soin","Consolida con attenzione"],["Combining warehouse items can reduce repeated base charges, but a very large or mixed parcel may narrow the routes available to you.","Combinar art\xEDculos del almac\xE9n puede reducir cargos base repetidos, pero un paquete muy grande o mixto puede limitar las rutas disponibles.","Das Zusammenlegen von Lagerartikeln kann wiederholte Grundgeb\xFChren senken, doch ein sehr gro\xDFes oder gemischtes Paket kann die verf\xFCgbaren Routen einschr\xE4nken.","Regrouper des articles d'entrep\xF4t peut r\xE9duire les frais de base r\xE9p\xE9t\xE9s, mais un colis tr\xE8s volumineux ou mixte peut limiter les lignes disponibles.","Unire articoli in magazzino pu\xF2 ridurre i costi base ripetuti, ma un pacco molto grande o misto pu\xF2 limitare le linee disponibili."],["REHEARSAL","ENSAYO","PROBEPACKEN","SIMULATION","PROVA"],["Preview the package","Previsualiza el paquete","Paket vorab pr\xFCfen","Pr\xE9visualisez le colis","Visualizza l'imballaggio"],["LoloBuy describes rehearsal as pre-packing, not a real parcel. It can provide weight and size information before you submit the actual shipment.","LoloBuy describe el ensayo como un preembalaje, no como un paquete real. Puede proporcionar datos de peso y tama\xF1o antes de enviar el paquete definitivo.","LoloBuy beschreibt Rehearsal als Vorverpackung, nicht als echtes Paket. So k\xF6nnen Gewicht und Ma\xDFe vor der tats\xE4chlichen Paketeinreichung ermittelt werden.","LoloBuy d\xE9crit la simulation comme un pr\xE9-emballage, et non comme un colis r\xE9el. Elle peut fournir le poids et les dimensions avant la soumission de l'envoi r\xE9el.","LoloBuy descrive la prova come pre-imballaggio, non come pacco reale. Pu\xF2 fornire peso e dimensioni prima dell'invio effettivo."],["Decision-first reading","Lectura orientada a decisiones","Entscheidungsorientiert lesen","Lecture ax\xE9e sur la d\xE9cision","Lettura orientata alle decisioni"],["What to check before ordering","Qu\xE9 revisar antes de pedir","Was du vor der Bestellung pr\xFCfen solltest","Ce qu'il faut v\xE9rifier avant de commander","Cosa controllare prima di ordinare"],["Useful product research should change what you check\u2014not merely repeat the phrase \u201CLoloBuy spreadsheet.\u201D","Una investigaci\xF3n \xFAtil debe cambiar lo que compruebas, no limitarse a repetir la frase \xABLoloBuy spreadsheet\xBB.","Gute Produktrecherche sollte ver\xE4ndern, was du pr\xFCfst \u2013 nicht nur den Begriff \u201ELoloBuy Spreadsheet\u201C wiederholen.","Une recherche utile doit changer ce que vous v\xE9rifiez, pas simplement r\xE9p\xE9ter l'expression \xAB LoloBuy spreadsheet \xBB.","Una ricerca utile deve cambiare ci\xF2 che controlli, non limitarsi a ripetere \u201CLoloBuy spreadsheet\u201D."],["BUYING BASICS \xB7 6 MIN","CONCEPTOS DE COMPRA \xB7 6 MIN","KAUFGRUNDLAGEN \xB7 6 MIN","BASES DE L'ACHAT \xB7 6 MIN","BASI DELL'ACQUISTO \xB7 6 MIN"],["Why the listing variant matters more than the thumbnail","Por qu\xE9 la variante del anuncio importa m\xE1s que la miniatura","Warum die Angebotsvariante wichtiger ist als das Vorschaubild","Pourquoi la variante de l'annonce compte plus que la miniature","Perch\xE9 la variante dell'inserzione conta pi\xF9 della miniatura"],["Marketplace pages can group many colors, batches or versions under one image. Confirm the exact selected option and preserve any useful note for the purchasing agent.","Las p\xE1ginas de los mercados pueden agrupar muchos colores, lotes o versiones bajo una imagen. Confirma la opci\xF3n exacta y conserva cualquier nota \xFAtil para el agente de compra.","Marktplatzseiten k\xF6nnen viele Farben, Chargen oder Versionen unter einem Bild b\xFCndeln. Pr\xFCfe die genau gew\xE4hlte Option und bewahre hilfreiche Hinweise f\xFCr den Einkaufsagenten auf.","Les pages de marketplace peuvent regrouper plusieurs couleurs, lots ou versions sous une seule image. Confirmez l'option exacte et conservez toute note utile pour l'agent d'achat.","Le pagine dei marketplace possono raggruppare colori, lotti o versioni sotto una sola immagine. Conferma l'opzione esatta e conserva le note utili per l'agente d'acquisto."],["Read the buying flow","Leer el proceso de compra","Kaufablauf lesen","Lire le processus d'achat","Leggi la procedura d'acquisto"],["QC NOTES \xB7 7 MIN","NOTAS DE QC \xB7 7 MIN","QC-HINWEISE \xB7 7 MIN","NOTES QC \xB7 7 MIN","NOTE QC \xB7 7 MIN"],["A repeatable warehouse-photo checklist","Una lista repetible para fotos de almac\xE9n","Eine wiederholbare Checkliste f\xFCr Lagerfotos","Une liste reproductible pour les photos d'entrep\xF4t","Una checklist ripetibile per le foto di magazzino"],["Start with identity and variant, then move to visible condition, labels, symmetry and the specific details that matter for that product type.","Empieza por la identidad y la variante; despu\xE9s revisa el estado visible, las etiquetas, la simetr\xEDa y los detalles importantes para ese tipo de producto.","Beginne mit Identit\xE4t und Variante, dann pr\xFCfe sichtbaren Zustand, Etiketten, Symmetrie und die f\xFCr den Produkttyp wichtigen Details.","Commencez par l'identit\xE9 et la variante, puis examinez l'\xE9tat visible, les \xE9tiquettes, la sym\xE9trie et les d\xE9tails propres \xE0 ce type de produit.","Inizia da identit\xE0 e variante, poi controlla condizioni visibili, etichette, simmetria e dettagli specifici del tipo di prodotto."],["Use the QC checklist","Usar la lista de QC","QC-Checkliste nutzen","Utiliser la liste QC","Usa la checklist QC"],["SHIPPING \xB7 8 MIN","ENV\xCDOS \xB7 8 MIN","VERSAND \xB7 8 MIN","LIVRAISON \xB7 8 MIN","SPEDIZIONE \xB7 8 MIN"],["How parcel dimensions can change the route decision","C\xF3mo las dimensiones del paquete pueden cambiar la elecci\xF3n de ruta","Wie Paketma\xDFe die Routenwahl ver\xE4ndern k\xF6nnen","Comment les dimensions du colis peuvent changer le choix de ligne","Come le dimensioni del pacco possono cambiare la scelta della linea"],["Estimate with realistic dimensions, understand chargeable weight and compare route restrictions before adding packaging services.","Estima con dimensiones realistas, entiende el peso facturable y compara las restricciones antes de a\xF1adir servicios de embalaje.","Sch\xE4tze mit realistischen Ma\xDFen, verstehe das abrechenbare Gewicht und vergleiche Routenbeschr\xE4nkungen, bevor du Verpackungsdienste hinzuf\xFCgst.","Estimez avec des dimensions r\xE9alistes, comprenez le poids facturable et comparez les restrictions avant d'ajouter des services d'emballage.","Stima con dimensioni realistiche, comprendi il peso addebitabile e confronta le restrizioni prima di aggiungere servizi di imballaggio."],["Review parcel planning","Revisar la planificaci\xF3n del paquete","Paketplanung pr\xFCfen","Revoir la planification du colis","Rivedi la pianificazione del pacco"],["View all buying guides","Ver todas las gu\xEDas de compra","Alle Kaufratgeber ansehen","Voir tous les guides d'achat","Vedi tutte le guide all'acquisto"],["Each guide focuses on a specific decision: product selection, warehouse-photo review or parcel planning.","Cada gu\xEDa se centra en una decisi\xF3n concreta: selecci\xF3n del producto, revisi\xF3n de fotos de almac\xE9n o planificaci\xF3n del paquete.","Jeder Ratgeber behandelt eine konkrete Entscheidung: Produktauswahl, Lagerfoto-Pr\xFCfung oder Paketplanung.","Chaque guide se concentre sur une d\xE9cision pr\xE9cise : s\xE9lection du produit, examen des photos d'entrep\xF4t ou planification du colis.","Ogni guida si concentra su una decisione precisa: scelta del prodotto, controllo delle foto di magazzino o pianificazione del pacco."],["Clear answers","Respuestas claras","Klare Antworten","R\xE9ponses claires","Risposte chiare"],["LoloBuy spreadsheet FAQ","Preguntas frecuentes sobre la hoja LoloBuy","FAQ zum LoloBuy Spreadsheet","FAQ sur la feuille LoloBuy","FAQ sul foglio LoloBuy"],["Short answers to the questions that matter before you leave the product-discovery stage.","Respuestas breves a las preguntas importantes antes de pasar de la fase de descubrimiento del producto.","Kurze Antworten auf wichtige Fragen, bevor du die Produktsuche abschlie\xDFt.","Des r\xE9ponses courtes aux questions importantes avant de quitter l'\xE9tape de d\xE9couverte du produit.","Risposte brevi alle domande importanti prima di lasciare la fase di ricerca del prodotto."],["Open the complete FAQ","Abrir todas las preguntas frecuentes","Vollst\xE4ndige FAQ \xF6ffnen","Ouvrir la FAQ compl\xE8te","Apri tutte le FAQ"]],m=[["Products","Productos","Produkte","Produits","Prodotti"],["Categories","Categor\xEDas","Kategorien","Cat\xE9gories","Categorie"],["QC Guide","Gu\xEDa de QC","QC-Ratgeber","Guide QC","Guida QC"],["Shipping","Env\xEDos","Versand","Livraison","Spedizione"],["Buying Guides","Gu\xEDas de compra","Kaufratgeber","Guides d'achat","Guide all'acquisto"],["FAQ","Preguntas frecuentes","FAQ","FAQ","FAQ"],["EDITORIAL","EDITORIAL","REDAKTION","\xC9DITORIAL","REDAZIONE"],["LEGAL","LEGAL","RECHTLICHES","MENTIONS L\xC9GALES","INFORMAZIONI LEGALI"],["About","Acerca de","\xDCber uns","\xC0 propos","Chi siamo"],["Editorial policy","Pol\xEDtica editorial","Redaktionsrichtlinie","Politique \xE9ditoriale","Politica editoriale"],["Research method","M\xE9todo de investigaci\xF3n","Recherchemethodik","M\xE9thode de recherche","Metodo di ricerca"],["Contact","Contacto","Kontakt","Contact","Contatti"],["Privacy policy","Pol\xEDtica de privacidad","Datenschutzerkl\xE4rung","Politique de confidentialit\xE9","Informativa sulla privacy"],["Terms of use","Condiciones de uso","Nutzungsbedingungen","Conditions d'utilisation","Termini di utilizzo"],["Independent disclosure","Declaraci\xF3n de independencia","Unabh\xE4ngigkeitserkl\xE4rung","D\xE9claration d'ind\xE9pendance","Dichiarazione di indipendenza"],["Browse finds","Ver productos","Produkte ansehen","Voir les produits","Vedi prodotti"],["EXPLORE","EXPLORAR","ENTDECKEN","EXPLORER","ESPLORA"],["PLAN","PLANIFICAR","PLANEN","PLANIFIER","PIANIFICA"],["Product finds","Productos encontrados","Produktfunde","S\xE9lection de produits","Prodotti trovati"],["QC guide","Gu\xEDa de QC","QC-Ratgeber","Guide QC","Guida QC"],["Buying flow","Proceso de compra","Kaufablauf","Processus d'achat","Procedura d'acquisto"],["Learn","Aprender","Lernen","Apprendre","Impara"],["Home","Inicio","Startseite","Accueil","Home"],["View","Ver","Ansehen","Voir","Vedi"],["Open product","Abrir producto","Produkt \xF6ffnen","Ouvrir le produit","Apri prodotto"],["Item page","P\xE1gina del producto","Artikelseite","Page du produit","Pagina prodotto"],["Search the product catalog","Buscar en el cat\xE1logo de productos","Produktkatalog durchsuchen","Rechercher dans le catalogue de produits","Cerca nel catalogo prodotti"],["Search the main product catalog","Buscar en el cat\xE1logo principal","Hauptkatalog durchsuchen","Rechercher dans le catalogue principal","Cerca nel catalogo principale"],["Search shoes, hoodies, watches...","Buscar calzado, sudaderas, relojes...","Schuhe, Hoodies, Uhren suchen...","Rechercher chaussures, sweats, montres...","Cerca scarpe, felpe, orologi..."],["Shoes","Calzado","Schuhe","Chaussures","Scarpe"],["Hoodies","Sudaderas","Hoodies","Sweats","Felpe"],["Jackets","Chaquetas","Jacken","Vestes","Giacche"],["Accessories","Accesorios","Accessoires","Accessoires","Accessori"],["Headwear","Sombreros y gorras","Kopfbedeckungen","Chapeaux et casquettes","Copricapi"],["Electronics","Electr\xF3nica","Elektronik","\xC9lectronique","Elettronica"],["Sweaters","Jers\xE9is","Pullover","Pulls","Maglioni"],["Clothing","Ropa","Bekleidung","V\xEAtements","Abbigliamento"],["Sneakers, runners and slides","Zapatillas, calzado deportivo y chanclas","Sneaker, Laufschuhe und Slides","Baskets, chaussures de course et claquettes","Sneaker, scarpe da corsa e ciabatte"],["Hoodies, sweaters and layers","Sudaderas, jers\xE9is y prendas de capa","Hoodies, Pullover und Lagenlooks","Sweats, pulls et v\xEAtements superposables","Felpe, maglioni e capi a strati"],["Coats, jackets and outerwear","Abrigos, chaquetas y prendas exteriores","M\xE4ntel, Jacken und Oberbekleidung","Manteaux, vestes et v\xEAtements d'ext\xE9rieur","Cappotti, giacche e capispalla"],["Headwear, watches and more","Sombreros, relojes y m\xE1s","Kopfbedeckungen, Uhren und mehr","Chapeaux, montres et plus encore","Copricapi, orologi e altro"],["Neutral titles describe the visible item only. Third-party marks in source images belong to their owners and do not imply endorsement, authorization or authenticity.","Los t\xEDtulos neutros describen \xFAnicamente el art\xEDculo visible. Las marcas de terceros que aparecen en las im\xE1genes pertenecen a sus propietarios y no implican respaldo, autorizaci\xF3n ni autenticidad.","Neutrale Titel beschreiben nur den sichtbaren Artikel. Marken Dritter in Quellbildern geh\xF6ren ihren jeweiligen Inhabern und bedeuten keine Empfehlung, Genehmigung oder Echtheitsbest\xE4tigung.","Les titres neutres d\xE9crivent uniquement l'article visible. Les marques de tiers pr\xE9sentes dans les images appartiennent \xE0 leurs propri\xE9taires et n'impliquent ni approbation, ni autorisation, ni authenticit\xE9.","I titoli neutri descrivono solo l'articolo visibile. I marchi di terzi presenti nelle immagini appartengono ai rispettivi proprietari e non implicano approvazione, autorizzazione o autenticit\xE0."],["Read the independent disclosure.","Lee la declaraci\xF3n de independencia.","Unabh\xE4ngigkeitserkl\xE4rung lesen.","Lire la d\xE9claration d'ind\xE9pendance.","Leggi la dichiarazione di indipendenza."],["Cushioned trail running shoes","Zapatillas de trail con amortiguaci\xF3n","Ged\xE4mpfte Trail-Laufschuhe","Chaussures de trail amorties","Scarpe da trail ammortizzate"],["Graphic pullover hoodie collection","Colecci\xF3n de sudaderas gr\xE1ficas","Kollektion grafischer Kapuzenpullover","Collection de sweats graphiques","Collezione di felpe grafiche"],["Monogram-pattern baseball cap","Gorra con estampado monograma","Baseballkappe mit Monogrammmuster","Casquette \xE0 motif monogramme","Cappellino con motivo monogramma"],["Round digital smartwatch","Reloj inteligente digital redondo","Runde digitale Smartwatch","Montre connect\xE9e num\xE9rique ronde","Smartwatch digitale rotondo"],["High-top platform sneakers","Zapatillas altas con plataforma","High-Top-Plateau-Sneaker","Baskets montantes \xE0 plateforme","Sneaker alte con plateau"],["Cushioned slide sandals","Sandalias tipo pala acolchadas","Gepolsterte Badesandalen","Claquettes rembourr\xE9es","Ciabatte imbottite"],["Graphic knit sweater collection","Colecci\xF3n de jers\xE9is gr\xE1ficos","Kollektion grafischer Strickpullover","Collection de pulls graphiques","Collezione di maglioni grafici"],["Snow and ski goggles","Gafas para nieve y esqu\xED","Schnee- und Skibrille","Masque de neige et de ski","Maschera da neve e sci"],["Belted wool-blend coat","Abrigo de mezcla de lana con cintur\xF3n","Geg\xFCrteter Wollmix-Mantel","Manteau ceintur\xE9 en m\xE9lange de laine","Cappotto misto lana con cintura"],["Glitter low-top sneakers","Zapatillas bajas con brillo","Glitzernde Low-Top-Sneaker","Baskets basses paillet\xE9es","Sneaker basse glitterate"],["Long-sleeve polo shirts","Polos de manga larga","Lang\xE4rmlige Poloshirts","Polos \xE0 manches longues","Polo a maniche lunghe"],["Embroidered knit beanie","Gorro de punto bordado","Bestickte Strickm\xFCtze","Bonnet en maille brod\xE9","Berretto in maglia ricamato"],["Independent product discovery, QC notes and shipping context for people researching how to use LoloBuy.","Descubrimiento independiente de productos, notas de QC y contexto de env\xEDo para quienes investigan c\xF3mo usar LoloBuy.","Unabh\xE4ngige Produktsuche, QC-Hinweise und Versandinformationen f\xFCr alle, die sich \xFCber die Nutzung von LoloBuy informieren.","D\xE9couverte ind\xE9pendante de produits, notes de QC et contexte de livraison pour les personnes qui se renseignent sur LoloBuy.","Ricerca indipendente di prodotti, note QC e informazioni sulla spedizione per chi vuole capire come usare LoloBuy."],["This independent publication is not LoloBuy and is not endorsed by LoloBuy or any product brand. Product, category and search links promote the associated catalog at cnbuycha.com, so the operator may benefit commercially from visits or purchases. Verify every live listing before ordering.","Esta publicaci\xF3n independiente no es LoloBuy ni est\xE1 respaldada por LoloBuy o por ninguna marca. Los enlaces de productos, categor\xEDas y b\xFAsqueda promocionan el cat\xE1logo asociado de cnbuycha.com, por lo que el operador puede beneficiarse comercialmente de las visitas o compras. Verifica cada anuncio actual antes de pedir.","Diese unabh\xE4ngige Publikation ist weder LoloBuy noch von LoloBuy oder einer Produktmarke unterst\xFCtzt. Produkt-, Kategorie- und Suchlinks bewerben den verbundenen Katalog auf cnbuycha.com; der Betreiber kann daher wirtschaftlich von Besuchen oder K\xE4ufen profitieren. Pr\xFCfe vor der Bestellung jedes aktuelle Angebot.","Cette publication ind\xE9pendante n'est pas LoloBuy et n'est approuv\xE9e ni par LoloBuy ni par une marque de produits. Les liens produit, cat\xE9gorie et recherche font la promotion du catalogue associ\xE9 sur cnbuycha.com ; l'exploitant peut donc tirer un avantage commercial des visites ou achats. V\xE9rifiez chaque annonce actuelle avant de commander.","Questa pubblicazione indipendente non \xE8 LoloBuy e non \xE8 approvata da LoloBuy n\xE9 da alcun marchio. I link a prodotti, categorie e ricerca promuovono il catalogo associato su cnbuycha.com, quindi il gestore pu\xF2 trarre un vantaggio commerciale da visite o acquisti. Verifica ogni inserzione aggiornata prima di ordinare."],["\xA9 2026 LoloBuy Sheet \xB7 Catalog reviewed 29 July 2026","\xA9 2026 LoloBuy Sheet \xB7 Cat\xE1logo revisado el 29 de julio de 2026","\xA9 2026 LoloBuy Sheet \xB7 Katalog gepr\xFCft am 29. Juli 2026","\xA9 2026 LoloBuy Sheet \xB7 Catalogue v\xE9rifi\xE9 le 29 juillet 2026","\xA9 2026 LoloBuy Sheet \xB7 Catalogo verificato il 29 luglio 2026"],["What is a LoloBuy spreadsheet?","\xBFQu\xE9 es una hoja de c\xE1lculo de LoloBuy?","Was ist ein LoloBuy Spreadsheet?","Qu'est-ce qu'une feuille de calcul LoloBuy ?","Che cos'\xE8 un foglio LoloBuy?"],["It is an independent product-discovery directory that organizes marketplace finds into searchable pages. It helps you locate a source item; it does not replace an agent's ordering, warehouse or international-shipping services.","Es un directorio independiente de descubrimiento de productos que organiza hallazgos de mercados en p\xE1ginas consultables. Ayuda a localizar el art\xEDculo de origen; no sustituye los servicios de compra, almac\xE9n o env\xEDo internacional de un agente.","Es ist ein unabh\xE4ngiges Verzeichnis zur Produktsuche, das Marktplatzfunde auf durchsuchbaren Seiten ordnet. Es hilft, den Ursprungsartikel zu finden, ersetzt aber nicht Bestellung, Lagerung oder internationalen Versand durch einen Agenten.","C'est un r\xE9pertoire ind\xE9pendant de d\xE9couverte de produits qui organise des trouvailles de marketplaces sur des pages consultables. Il aide \xE0 retrouver l'article source, mais ne remplace pas les services de commande, d'entrep\xF4t ou d'exp\xE9dition internationale d'un agent.","\xC8 una directory indipendente per la scoperta dei prodotti che organizza gli articoli trovati sui marketplace in pagine ricercabili. Aiuta a individuare l'articolo originale, ma non sostituisce i servizi di ordine, magazzino o spedizione internazionale di un agente."],["Do these product cards open the matching item?","\xBFEstas tarjetas abren el art\xEDculo correspondiente?","\xD6ffnen diese Produktkarten den passenden Artikel?","Ces fiches ouvrent-elles l'article correspondant ?","Queste schede aprono l'articolo corrispondente?"],["Yes. Each visible card uses the first image from the same destination product page, and its image, title and View control point to that exact main-site item.","S\xED. Cada tarjeta visible usa la primera imagen de la misma p\xE1gina de destino; la imagen, el t\xEDtulo y el bot\xF3n Ver apuntan exactamente a ese art\xEDculo del sitio principal.","Ja. Jede sichtbare Karte verwendet das erste Bild derselben Ziel-Produktseite. Bild, Titel und die Schaltfl\xE4che \u201EAnsehen\u201C f\xFChren genau zu diesem Artikel auf der Hauptseite.","Oui. Chaque fiche visible utilise la premi\xE8re image de la m\xEAme page produit de destination ; son image, son titre et le bouton Voir pointent vers cet article pr\xE9cis du site principal.","S\xEC. Ogni scheda visibile usa la prima immagine della stessa pagina prodotto di destinazione; immagine, titolo e comando Vedi portano esattamente a quell'articolo del sito principale."],["Where does the product search go?","\xBFAd\xF3nde lleva la b\xFAsqueda de productos?","Wohin f\xFChrt die Produktsuche?","O\xF9 m\xE8ne la recherche de produits ?","Dove porta la ricerca dei prodotti?"],["The search field sends the exact keyword to the main catalog's search-results page. It does not send visitors to LoloBuy or to another third-party directory.","El campo de b\xFAsqueda env\xEDa la palabra exacta a la p\xE1gina de resultados del cat\xE1logo principal. No dirige a los visitantes a LoloBuy ni a otro directorio de terceros.","Das Suchfeld \xFCbergibt das genaue Stichwort an die Suchergebnisse des Hauptkatalogs. Besucher werden weder zu LoloBuy noch zu einem anderen Drittanbieter-Verzeichnis geschickt.","Le champ de recherche envoie le mot-cl\xE9 exact vers la page de r\xE9sultats du catalogue principal. Il ne redirige pas les visiteurs vers LoloBuy ni vers un autre r\xE9pertoire tiers.","Il campo di ricerca invia la parola chiave esatta alla pagina dei risultati del catalogo principale. Non porta i visitatori a LoloBuy n\xE9 a directory di terze parti."],["Are the products guaranteed to be in stock?","\xBFSe garantiza que los productos est\xE9n disponibles?","Sind die Produkte garantiert auf Lager?","Les produits sont-ils garantis en stock ?","I prodotti sono garantiti disponibili?"],["No. Seller inventory, variants, pricing and links can change after a catalog review. Re-open the destination page and confirm the current listing before placing an order.","No. El inventario, las variantes, los precios y los enlaces del vendedor pueden cambiar despu\xE9s de una revisi\xF3n del cat\xE1logo. Vuelve a abrir la p\xE1gina de destino y confirma el anuncio actual antes de pedir.","Nein. Bestand, Varianten, Preise und Links des Verk\xE4ufers k\xF6nnen sich nach einer Katalogpr\xFCfung \xE4ndern. \xD6ffne die Zielseite erneut und pr\xFCfe das aktuelle Angebot vor der Bestellung.","Non. Le stock, les variantes, les prix et les liens du vendeur peuvent changer apr\xE8s la v\xE9rification du catalogue. Rouvrez la page de destination et confirmez l'annonce actuelle avant de commander.","No. Disponibilit\xE0, varianti, prezzi e link del venditore possono cambiare dopo la revisione del catalogo. Riapri la pagina di destinazione e verifica l'inserzione aggiornata prima di ordinare."],["Does a warehouse photo prove product quality?","\xBFUna foto de almac\xE9n demuestra la calidad del producto?","Beweist ein Lagerfoto die Produktqualit\xE4t?","Une photo d'entrep\xF4t prouve-t-elle la qualit\xE9 du produit ?","Una foto di magazzino dimostra la qualit\xE0 del prodotto?"],["It can reveal visible differences or damage, but it cannot guarantee fit, hidden construction, material composition, authenticity or durability. Use it as one part of your review.","Puede mostrar diferencias visibles o da\xF1os, pero no garantiza el ajuste, la construcci\xF3n interna, la composici\xF3n del material, la autenticidad ni la durabilidad. \xDAsala como una parte de tu revisi\xF3n.","Es kann sichtbare Abweichungen oder Sch\xE4den zeigen, garantiert aber weder Passform, verborgene Verarbeitung, Materialzusammensetzung, Echtheit noch Haltbarkeit. Nutze es als einen Teil deiner Pr\xFCfung.","Elle peut r\xE9v\xE9ler des diff\xE9rences visibles ou des dommages, mais ne garantit ni la coupe, ni la construction cach\xE9e, ni la composition, l'authenticit\xE9 ou la durabilit\xE9. Utilisez-la comme un \xE9l\xE9ment de votre v\xE9rification.","Pu\xF2 mostrare differenze visibili o danni, ma non garantisce vestibilit\xE0, costruzione interna, composizione dei materiali, autenticit\xE0 o durata. Usala come parte della verifica."],["What should I check in a QC photo?","\xBFQu\xE9 debo revisar en una foto de QC?","Was sollte ich auf einem QC-Foto pr\xFCfen?","Que faut-il v\xE9rifier sur une photo QC ?","Cosa devo controllare in una foto QC?"],["Start with item identity, selected color or variant, the visible size label, obvious marks or damage, missing pieces and any product-specific detail that affected your choice.","Empieza por la identidad del art\xEDculo, el color o la variante elegidos, la etiqueta de talla visible, marcas o da\xF1os evidentes, piezas faltantes y cualquier detalle espec\xEDfico que influyera en tu elecci\xF3n.","Beginne mit Artikelidentit\xE4t, gew\xE4hlter Farbe oder Variante, sichtbarem Gr\xF6\xDFenetikett, offensichtlichen Spuren oder Sch\xE4den, fehlenden Teilen und allen produktspezifischen Details, die deine Wahl beeinflusst haben.","Commencez par l'identit\xE9 de l'article, la couleur ou variante choisie, l'\xE9tiquette de taille visible, les marques ou dommages \xE9vidents, les pi\xE8ces manquantes et tout d\xE9tail sp\xE9cifique ayant influenc\xE9 votre choix.","Inizia da identit\xE0 dell'articolo, colore o variante selezionati, etichetta della taglia visibile, segni o danni evidenti, parti mancanti e dettagli specifici che hanno influito sulla scelta."],["What can change an international shipping estimate?","\xBFQu\xE9 puede cambiar una estimaci\xF3n de env\xEDo internacional?","Was kann eine internationale Versandsch\xE4tzung ver\xE4ndern?","Qu'est-ce qui peut modifier une estimation d'exp\xE9dition internationale ?","Cosa pu\xF2 cambiare una stima di spedizione internazionale?"],["Destination, available route, actual weight, parcel dimensions, route restrictions, consolidation and packing choices can all change the result. Treat an early estimate as a planning figure rather than a guaranteed charge.","El destino, la ruta disponible, el peso real, las dimensiones, las restricciones, la consolidaci\xF3n y el embalaje pueden cambiar el resultado. Trata una estimaci\xF3n inicial como una cifra de planificaci\xF3n, no como un coste garantizado.","Ziel, verf\xFCgbare Route, tats\xE4chliches Gewicht, Paketma\xDFe, Routenbeschr\xE4nkungen, Zusammenlegung und Verpackung k\xF6nnen das Ergebnis ver\xE4ndern. Eine fr\xFChe Sch\xE4tzung ist ein Planungswert, kein garantierter Preis.","La destination, la ligne disponible, le poids r\xE9el, les dimensions, les restrictions, la consolidation et l'emballage peuvent modifier le r\xE9sultat. Consid\xE9rez une estimation initiale comme un rep\xE8re, pas comme un tarif garanti.","Destinazione, linea disponibile, peso reale, dimensioni, restrizioni, consolidamento e imballaggio possono cambiare il risultato. Considera una stima iniziale come dato di pianificazione, non come costo garantito."],["Is this an official LoloBuy website?","\xBFEs este un sitio web oficial de LoloBuy?","Ist dies eine offizielle LoloBuy-Website?","S'agit-il d'un site officiel de LoloBuy ?","Questo \xE8 un sito ufficiale LoloBuy?"],["No. This is an independent product-discovery and educational site. It does not claim to be LoloBuy and does not sell, inspect, store or ship products.","No. Es un sitio independiente de descubrimiento de productos y educaci\xF3n. No afirma ser LoloBuy y no vende, inspecciona, almacena ni env\xEDa productos.","Nein. Dies ist eine unabh\xE4ngige Website zur Produktsuche und Information. Sie gibt sich nicht als LoloBuy aus und verkauft, pr\xFCft, lagert oder versendet keine Produkte.","Non. Il s'agit d'un site ind\xE9pendant de d\xE9couverte de produits et d'information. Il ne pr\xE9tend pas \xEAtre LoloBuy et ne vend, n'inspecte, ne stocke ni n'exp\xE9die de produits.","No. \xC8 un sito indipendente di scoperta prodotti e informazione. Non dichiara di essere LoloBuy e non vende, ispeziona, conserva o spedisce prodotti."]],d={en:"English",es:"Espa\xF1ol",de:"Deutsch",fr:"Fran\xE7ais",it:"Italiano"},c=[...m,...p,...u];function t(a){return Object.fromEntries(c.map(i=>[i[0],i[a]]))}t(1),t(2),t(3),t(4);new Set(c.map(a=>a[0]));var g=["es","de","fr","it"],h=["/","/products","/categories","/qc-guide","/shipping","/articles","/faq","/how-it-works"];function v(a){return g.includes(a)}function f(a){return h.includes(a)}function b(a){let i=a.split("/");v(i[1])&&i.splice(1,1);let e=i.join("/")||"/";return e.startsWith("/")?e:`/${e}`}function z(a,i){if(!i.startsWith("/")||i.startsWith("//")||i.startsWith("/assets/")||i.startsWith("/products/"))return i;let e=new URL(i,"https://lolobuy-sheet.net"),n=b(e.pathname).replace(/\/+$/,"")||"/",r=/^\/articles\/[^/]+$/.test(n);return!f(n)&&!r?`${n}${e.search}${e.hash}`:`${a==="en"?n:n==="/"?`/${a}`:`/${a}${n}`}${e.search}${e.hash}`}var o=l();function L({locale:a}){function i(e){let n=new URL(window.location.href),r=z(e,n.pathname);window.location.assign(`${r}${n.search}${n.hash}`)}return(0,o.jsxs)("label",{className:"language-module","data-i18n-ignore":!0,children:[(0,o.jsx)("span",{"aria-hidden":"true",children:"\u6587"}),(0,o.jsx)("span",{className:"sr-only",children:"Select language"}),(0,o.jsx)("select",{"aria-label":"Select language",value:a,onChange:e=>i(e.target.value),children:Object.keys(d).map(e=>(0,o.jsx)("option",{value:e,children:d[e]},e))})]})}export{L as LanguageModule};
